DO $audit28$
DECLARE
  old_reading jsonb := $old${"title":"Ποτέραν ὁδὸν αἱρήσεται ὁ Ἡρακλῆς;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 2.1.21–34, Socrates’ retelling of Prodicus’ Choice of Heracles. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","This is an allegory attributed to Prodicus within Xenophon’s Socratic dialogue. The speeches are drastically shortened and newly worded. The reader’s final question is supplied; no historical meeting is asserted.","Demonstratives and questions distinguish two speakers, their promises, and the paths they recommend."],"paragraphs":[{"greek":"Ὁ Ἡρακλῆς νέος ὢν ἐν ἡσυχίᾳ ἐκάθητο. περὶ τοῦ βίου ἐσκόπει· ποτέραν ὁδὸν αἱρήσεται; δύο γυναῖκες προσῆλθον. ἡ μὲν Ἀρετὴ ἦν, ἡ δὲ Κακία.","gloss":[{"greek":"ὢν","english":"being; participle of εἰμί"},{"greek":"ἐκάθητο","english":"was sitting"},{"greek":"ποτέραν","english":"which of two; feminine accusative"},{"greek":"αἱρήσεται","english":"will choose"},{"greek":"προσῆλθον","english":"approached"},{"greek":"Ἀρετὴ","english":"Virtue; personification"},{"greek":"Κακία","english":"Vice; personification"}]},{"greek":"Ἡ Κακία πρώτη λέγει· «ἥδε ἡ ὁδὸς ἡδεῖά ἐστιν. δεῦρο ἐλθέ. ἐνταῦθα σῖτον καὶ ποτὸν εὑρήσεις. οὐ πολλοὺς πόνους ἕξεις.»","gloss":[{"greek":"πρώτη","english":"first; feminine"},{"greek":"ἥδε ἡ ὁδὸς","english":"this road here"},{"greek":"δεῦρο","english":"here, hither"},{"greek":"ἐνταῦθα","english":"here, there"},{"greek":"εὑρήσεις","english":"will find"},{"greek":"ἕξεις","english":"will have"}]},{"greek":"«Τίνες τὸν σῖτον παρασκευάζουσιν; πόθεν τὰ χρήματα;» ταύτας τὰς ἐρωτήσεις ὁ ἀναγινώσκων νῦν ἐρωτᾷ. ἡ μὲν ἐπαγγελία ἡδεῖά ἐστιν· ἡ δὲ ἐργασία τίνος;","gloss":[{"greek":"Τίνες","english":"who? plural"},{"greek":"πόθεν","english":"from where?"},{"greek":"ταύτας τὰς ἐρωτήσεις","english":"these questions"},{"greek":"ὁ ἀναγινώσκων","english":"the reader"},{"greek":"ἐπαγγελία","english":"promise"},{"greek":"τίνος","english":"whose?"}]},{"greek":"Ἡ δὲ Ἀρετὴ λέγει· «ἐκείνη ἡ ὁδὸς ἄλλην ἐλπίδα παρέχει. οὐδὲν τῶν καλῶν ἄνευ πόνου οἱ θεοὶ διδόασιν. τοῖς φίλοις βοήθει καὶ τὰ καλὰ πράττε.»","gloss":[{"greek":"ἐκείνη ἡ ὁδὸς","english":"that road"},{"greek":"ἐλπίδα","english":"hope"},{"greek":"οὐδὲν","english":"none, nothing"},{"greek":"ἄνευ πόνου","english":"without toil"},{"greek":"διδόασιν","english":"give; supported -μι form"},{"greek":"βοήθει","english":"help; imperative"}]},{"greek":"Ἑκατέρα γυνὴ περὶ εὐδαιμονίας λέγει. ἡ μὲν τὴν νῦν ἡδονὴν δεικνύει, ἡ δὲ τὸν ἔπειτα βίον. οὐ πᾶσα ἡδονὴ κακή· τίς δὲ ἡδονὴ τοὺς φίλους βλάπτει;","gloss":[{"greek":"Ἑκατέρα","english":"each of two"},{"greek":"εὐδαιμονίας","english":"happiness"},{"greek":"δεικνύει","english":"shows; supported verb"},{"greek":"ἔπειτα","english":"afterwards"},{"greek":"βλάπτει","english":"harms"}]},{"greek":"Οὗτος ὁ μῦθος οὐχ ἱστορία μάχης ἐστίν. πρόκεινται δύο βίοι. τίνα βίον θαυμάζεις; πῶς κρίνεις τὰς ἐπαγγελίας; ἡ καλὴ ὄψις οὐ μόνη τὴν ἀλήθειαν δηλοῖ.","gloss":[{"greek":"Οὗτος ὁ μῦθος","english":"this tale"},{"greek":"πρόκεινται","english":"lie before us; supported form"},{"greek":"πῶς","english":"how?"},{"greek":"κρίνεις","english":"you judge"},{"greek":"ὄψις","english":"appearance"},{"greek":"δηλοῖ","english":"reveals; supported -όω contract"}]}],"translation":"Heracles, when young, was sitting in a quiet place. He was considering his life: which of two roads will he choose? Two women approached. One was Virtue, the other Vice.\n\nVice speaks first: “This road here is pleasant. Come here. Here you will find food and drink. You will not have many toils.”\n\n“Who prepares the food? Where do the resources come from?” The reader now asks these questions. The promise is pleasant; but whose is the work?\n\nVirtue says, “That road offers a different hope. The gods give none of the fine things without toil. Help your friends and do noble things.”\n\nEach woman speaks about happiness. One shows present pleasure, the other life afterwards. Not every pleasure is bad; but which pleasure harms friends?\n\nThis story is not an account of a battle. Two ways of life lie before us. Which life do you admire? How do you judge the promises? A fine appearance does not by itself reveal the truth.\n","sourceCitation":"Xenophon, Memorabilia 2.1.21–34, Socrates’ retelling of Prodicus’ Choice of Heracles. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm https://en.wikipedia.org/wiki/Memorabilia_(Xenophon) https://www.hs-augsburg.de/homes/harsch/graeca/Chronologia/S_ante05/Prodikos/pro_hera.html https://www.hs-augsburg.de/homes/harsch/graeca/Chronologia/S_ante05/Prodikos/pro_hera.html","notesMarkdown":"This is an allegory attributed to Prodicus within Xenophon’s Socratic dialogue. The speeches are drastically shortened and newly worded. The reader’s final question is supplied; no historical meeting is asserted."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ποτέραν ὁδὸν αἱρήσεται ὁ Ἡρακλῆς;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 2.1.21–34, Socrates’ retelling of Prodicus’ Choice of Heracles. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","This is an allegory attributed to Prodicus within Xenophon’s Socratic dialogue. The speeches are drastically shortened and newly worded. The reader’s final question is supplied; no historical meeting is asserted.","Demonstratives and questions distinguish two speakers, their promises, and the paths they recommend."],"paragraphs":[{"greek":"Ὁ Ἡρακλῆς νέος ὢν ἐν ἡσυχίᾳ ἐκάθητο. περὶ τοῦ βίου ἐσκόπει· ποτέραν ὁδὸν αἱρήσεται; δύο γυναῖκες προσῆλθον. ἡ μὲν Ἀρετὴ ἦν, ἡ δὲ Κακία.","gloss":[{"greek":"ὢν","english":"being; participle of εἰμί"},{"greek":"ἐκάθητο","english":"was sitting"},{"greek":"ποτέραν","english":"which of two; feminine accusative"},{"greek":"αἱρήσεται","english":"will choose"},{"greek":"προσῆλθον","english":"approached"},{"greek":"Ἀρετὴ","english":"Virtue; personification"},{"greek":"Κακία","english":"Vice; personification"}]},{"greek":"Ἡ Κακία πρώτη λέγει· «ἥδε ἡ ὁδὸς ἡδεῖά ἐστιν. δεῦρο ἐλθέ. ἐνταῦθα σῖτον καὶ ποτὸν εὑρήσεις. οὐ πολλοὺς πόνους ἕξεις.»","gloss":[{"greek":"πρώτη","english":"first; feminine"},{"greek":"ἥδε ἡ ὁδὸς","english":"this road here"},{"greek":"δεῦρο","english":"here, hither"},{"greek":"ἐνταῦθα","english":"here, there"},{"greek":"εὑρήσεις","english":"will find"},{"greek":"ἕξεις","english":"will have"}]},{"greek":"«Τίνες τὸν σῖτον παρασκευάζουσιν; πόθεν τὰ χρήματα;» ταύτας τὰς ἐρωτήσεις ὁ ἀναγινώσκων νῦν ἐρωτᾷ. ἡ μὲν ἐπαγγελία ἡδεῖά ἐστιν· ἡ δὲ ἐργασία τίνος;","gloss":[{"greek":"Τίνες","english":"who? plural"},{"greek":"πόθεν","english":"from where?"},{"greek":"ταύτας τὰς ἐρωτήσεις","english":"these questions"},{"greek":"ὁ ἀναγινώσκων","english":"the reader"},{"greek":"ἐπαγγελία","english":"promise"},{"greek":"τίνος","english":"whose?"}]},{"greek":"Ἡ δὲ Ἀρετὴ λέγει· «ἐκείνη ἡ ὁδὸς ἄλλην ἐλπίδα παρέχει. οὐδὲν τῶν καλῶν ἄνευ πόνου οἱ θεοὶ διδόασιν. τοῖς φίλοις βοήθει καὶ τὰ καλὰ πράττε.»","gloss":[{"greek":"ἐκείνη ἡ ὁδὸς","english":"that road"},{"greek":"ἐλπίδα","english":"hope"},{"greek":"οὐδὲν","english":"none, nothing"},{"greek":"ἄνευ πόνου","english":"without toil"},{"greek":"διδόασιν","english":"they give; present active of δίδωμι; read as a supported form before Lesson 34"},{"greek":"βοήθει","english":"help; imperative"}]},{"greek":"Ἑκατέρα γυνὴ περὶ εὐδαιμονίας λέγει. ἡ μὲν τὴν νῦν ἡδονὴν δεικνύει, ἡ δὲ τὸν ἔπειτα βίον. οὐ πᾶσα ἡδονὴ κακή· τίς δὲ ἡδονὴ τοὺς φίλους βλάπτει;","gloss":[{"greek":"Ἑκατέρα","english":"each of two"},{"greek":"εὐδαιμονίας","english":"happiness"},{"greek":"δεικνύει","english":"shows; present active of δείκνυμι; supported reading form before Lesson 36"},{"greek":"ἔπειτα","english":"afterwards"},{"greek":"βλάπτει","english":"harms"}]},{"greek":"Οὗτος ὁ μῦθος οὐχ ἱστορία μάχης ἐστίν. πρόκεινται δύο βίοι. τίνα βίον θαυμάζεις; πῶς κρίνεις τὰς ἐπαγγελίας; ἡ καλὴ ὄψις οὐ μόνη τὴν ἀλήθειαν δηλοῖ.","gloss":[{"greek":"Οὗτος ὁ μῦθος","english":"this tale"},{"greek":"πρόκεινται","english":"lie before us; supported form"},{"greek":"πῶς","english":"how?"},{"greek":"κρίνεις","english":"you judge"},{"greek":"ὄψις","english":"appearance"},{"greek":"δηλοῖ","english":"reveals; supported -όω contract"}]}],"translation":"Heracles, when young, was sitting in a quiet place. He was considering his life: which of two roads will he choose? Two women approached. One was Virtue, the other Vice.\n\nVice speaks first: “This road here is pleasant. Come here. Here you will find food and drink. You will not have many toils.”\n\n“Who prepares the food? Where do the resources come from?” The reader now asks these questions. The promise is pleasant; but whose is the work?\n\nVirtue says, “That road offers a different hope. The gods give none of the fine things without toil. Help your friends and do noble things.”\n\nEach woman speaks about happiness. One shows present pleasure, the other life afterwards. Not every pleasure is bad; but which pleasure harms friends?\n\nThis story is not an account of a battle. Two ways of life lie before us. Which life do you admire? How do you judge the promises? A fine appearance does not by itself reveal the truth.\n","sourceCitation":"Xenophon, Memorabilia 2.1.21–34, Socrates’ retelling of Prodicus’ Choice of Heracles. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm https://en.wikipedia.org/wiki/Memorabilia_(Xenophon) https://www.hs-augsburg.de/homes/harsch/graeca/Chronologia/S_ante05/Prodikos/pro_hera.html https://www.hs-augsburg.de/homes/harsch/graeca/Chronologia/S_ante05/Prodikos/pro_hera.html","notesMarkdown":"This is an allegory attributed to Prodicus within Xenophon’s Socratic dialogue. The speeches are drastically shortened and newly worded. The reader’s final question is supplied; no historical meeting is asserted."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-28' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 28 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit28$;
DO $audit29$
DECLARE
  old_reading jsonb := $old${"title":"Ἔστησαν ἐν τῇ χιόνι","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Anabasis 4.5.3–9. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The snow, unequal access to fires, hunger-collapse, and distribution of food follow Xenophon. The compact sequence and closing judgment are adapted. A soldier’s command in the grammar workshop is invented practice, not a quotation.","Read athematic aorists beside imperfect background and familiar thematic aorists."],"paragraphs":[{"greek":"Οἱ Ἕλληνες διὰ τῆς Ἀρμενίας ἐπορεύοντο. χιὼν πολλὴ ἦν, καὶ τὸ ψῦχος χαλεπὸν ἦν. οἱ στρατιῶται καὶ τὰ ὑποζύγια ἐπόνουν· οὐ πάντες τὸν πόνον ἤνεγκαν.","gloss":[{"greek":"τῆς Ἀρμενίας","english":"Armenia"},{"greek":"χιὼν","english":"snow"},{"greek":"τὸ ψῦχος","english":"the cold"},{"greek":"τὰ ὑποζύγια","english":"pack animals"},{"greek":"ἐπόνουν","english":"were toiling"},{"greek":"ἤνεγκαν","english":"endured; aorist of φέρω"}]},{"greek":"Πολλὰ μὲν τῶν ὑποζυγίων ἀπέθανεν, ἀπέθανον δὲ καὶ ἄνθρωποι. οὐ μόνον στρατιῶται ἀλλὰ καὶ δοῦλοι ἐν τῇ χιόνι ἦσαν. ὁ πόνος κοινὸς ἦν, ἡ δὲ δύναμις οὐκ ἴση.","gloss":[{"greek":"ἀπέθανεν","english":"died; neuter plural subject with singular verb"},{"greek":"ἀπέθανον","english":"died; plural"},{"greek":"δοῦλοι","english":"enslaved people"},{"greek":"κοινὸς","english":"shared"},{"greek":"δύναμις","english":"strength"},{"greek":"ἴση","english":"equal"}]},{"greek":"Οἱ πρῶτοι πῦρ ἔκαιον. οἱ δὲ ὕστερον ἐλθόντες τῷ πυρὶ προσῆλθον. οἱ πρῶτοι σῖτον ᾔτουν καὶ τότε τοὺς ἄλλους προσεδέχοντο.","gloss":[{"greek":"πῦρ","english":"fire"},{"greek":"ἔκαιον","english":"were burning"},{"greek":"ὕστερον","english":"later"},{"greek":"τῷ πυρὶ","english":"the fire; dative"},{"greek":"ᾔτουν","english":"were asking; imperfect of αἰτέω"},{"greek":"προσεδέχοντο","english":"were admitting; imperfect middle"}]},{"greek":"Τῇ ὑστεραίᾳ οἱ ἄνδρες πάλιν ἐπορεύοντο. τινὲς δὲ ἔπεσον καὶ ἔμειναν. ὁ Ξενοφῶν ἔστη παρὰ τοῖς ἀσθενέσιν· οὐκ ἔγνω εὐθὺς τὸ πάθος.","gloss":[{"greek":"Τῇ ὑστεραίᾳ","english":"on the next day"},{"greek":"ἔπεσον","english":"fell; thematic aorist"},{"greek":"ἔστη","english":"stood, stopped; athematic aorist"},{"greek":"τοῖς ἀσθενέσιν","english":"the weak men"},{"greek":"ἔγνω","english":"recognized; athematic aorist"},{"greek":"τὸ πάθος","english":"condition, suffering"}]},{"greek":"Ἀνήρ τις τὸ πάθος ἔγνω καὶ τῷ Ξενοφῶντι εἶπεν. ὁ δὲ παρὰ τὰ ὑποζύγια ἔβη καὶ σῖτον ἐζήτει. οἱ δυνατοὶ ἔφερον τὸν σῖτον τοῖς ἀσθενέσιν.","gloss":[{"greek":"Ἀνήρ τις","english":"a certain man"},{"greek":"ἔβη","english":"went; athematic aorist of βαίνω"},{"greek":"ἐζήτει","english":"was seeking"},{"greek":"οἱ δυνατοὶ","english":"those able, the strong"},{"greek":"ἔφερον","english":"were carrying"}]},{"greek":"Οἱ ἀσθενεῖς ἔφαγον, εἶτα ἀνέστησαν καὶ ἐπορεύοντο. οὐ λόγος μόνον αὐτοὺς ἔσωσεν. τροφῆς γὰρ ἐδέοντο. ἐνταῦθα ἡ ἐπιμέλεια τοῖς φίλοις κέρδος ἔφερεν.","gloss":[{"greek":"ἔφαγον","english":"ate; thematic aorist"},{"greek":"ἀνέστησαν","english":"got up; athematic aorist"},{"greek":"τροφῆς","english":"nourishment; genitive"},{"greek":"ἐδέοντο","english":"needed"},{"greek":"ἡ ἐπιμέλεια","english":"care"},{"greek":"κέρδος","english":"benefit"}]}],"translation":"The Greeks were marching through Armenia. There was much snow, and the cold was severe. The soldiers and pack animals struggled; not all endured the hardship.\n\nMany of the pack animals died, and people died too. Not only soldiers but also enslaved people were in the snow. The hardship was shared, but their strength was not equal.\n\nThose who arrived first were keeping a fire burning. Those who came later approached the fire. The first arrivals demanded food and only then admitted the others.\n\nOn the next day the men were marching again. Some fell and remained behind. Xenophon stopped beside the weak men; he did not immediately recognize their condition.\n\nA man recognized the condition and told Xenophon. Xenophon went to the pack animals and looked for food. Those who were strong carried the food to the weak.\n\nThe weak men ate, then got up and continued marching. Words alone did not save them. For they needed nourishment. Here care brought benefit to their companions.\n","sourceCitation":"Xenophon, Anabasis 4.5.3–9. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1170/1170-h/1170-h.htm https://en.wikipedia.org/wiki/Anabasis_(Xenophon) https://en.wikisource.org/wiki/Anabasis_(Dakyns)/Book_4/Chapter_5","notesMarkdown":"The snow, unequal access to fires, hunger-collapse, and distribution of food follow Xenophon. The compact sequence and closing judgment are adapted. A soldier’s command in the grammar workshop is invented practice, not a quotation."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ἔστησαν ἐν τῇ χιόνι","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Anabasis 4.5.3–9. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The snow, unequal access to fires, hunger-collapse, and distribution of food follow Xenophon. The compact sequence and closing judgment are adapted. A soldier’s command in the grammar workshop is invented practice, not a quotation.","Read athematic aorists beside imperfect background and familiar thematic aorists."],"paragraphs":[{"greek":"Οἱ Ἕλληνες διὰ τῆς Ἀρμενίας ἐπορεύοντο. χιὼν πολλὴ ἦν, καὶ τὸ ψῦχος χαλεπὸν ἦν. οἱ στρατιῶται καὶ τὰ ὑποζύγια ἐπόνουν· οὐ πάντες τὸν πόνον ἤνεγκαν.","gloss":[{"greek":"τῆς Ἀρμενίας","english":"Armenia"},{"greek":"χιὼν","english":"snow"},{"greek":"τὸ ψῦχος","english":"the cold"},{"greek":"τὰ ὑποζύγια","english":"pack animals"},{"greek":"ἐπόνουν","english":"were toiling"},{"greek":"ἤνεγκαν","english":"endured; aorist of φέρω"}]},{"greek":"Πολλὰ μὲν τῶν ὑποζυγίων ἀπέθανεν, ἀπέθανον δὲ καὶ ἄνθρωποι. οὐ μόνον στρατιῶται ἀλλὰ καὶ δοῦλοι ἐν τῇ χιόνι ἦσαν. ὁ πόνος κοινὸς ἦν, ἡ δὲ δύναμις οὐκ ἴση.","gloss":[{"greek":"ἀπέθανεν","english":"died; neuter plural subject with singular verb"},{"greek":"ἀπέθανον","english":"died; plural"},{"greek":"δοῦλοι","english":"enslaved people"},{"greek":"κοινὸς","english":"shared"},{"greek":"δύναμις","english":"strength"},{"greek":"ἴση","english":"equal"}]},{"greek":"Οἱ πρῶτοι πῦρ ἔκαιον. οἱ δὲ ὕστερον ἐλθόντες τῷ πυρὶ προσῆλθον. οἱ πρῶτοι σῖτον ᾔτουν καὶ τότε τοὺς ἄλλους προσεδέχοντο.","gloss":[{"greek":"πῦρ","english":"fire"},{"greek":"ἔκαιον","english":"were burning"},{"greek":"ὕστερον","english":"later"},{"greek":"τῷ πυρὶ","english":"the fire; dative"},{"greek":"ᾔτουν","english":"were asking; imperfect of αἰτέω"},{"greek":"προσεδέχοντο","english":"were admitting; imperfect middle"}]},{"greek":"Τῇ ὑστεραίᾳ οἱ ἄνδρες πάλιν ἐπορεύοντο. τινὲς δὲ ἔπεσον καὶ ἔμειναν. ὁ Ξενοφῶν ἔστη παρὰ τοῖς ἀσθενέσιν· οὐκ ἔγνω εὐθὺς τὸ πάθος.","gloss":[{"greek":"Τῇ ὑστεραίᾳ","english":"on the next day"},{"greek":"ἔπεσον","english":"fell; thematic aorist"},{"greek":"ἔστη","english":"stood, stopped; athematic aorist"},{"greek":"τοῖς ἀσθενέσιν","english":"the weak men"},{"greek":"ἔγνω","english":"recognized; athematic aorist"},{"greek":"τὸ πάθος","english":"condition, suffering"}]},{"greek":"Ἀνήρ τις τὸ πάθος ἔγνω καὶ τῷ Ξενοφῶντι εἶπεν. ὁ δὲ παρὰ τὰ ὑποζύγια ἔβη καὶ σῖτον ἐζήτει. οἱ δυνατοὶ ἔφερον τὸν σῖτον τοῖς ἀσθενέσιν.","gloss":[{"greek":"Ἀνήρ τις","english":"a certain man"},{"greek":"ἔβη","english":"went; athematic aorist of βαίνω"},{"greek":"ἐζήτει","english":"was seeking"},{"greek":"οἱ δυνατοὶ","english":"those able, the strong"},{"greek":"ἔφερον","english":"were carrying"}]},{"greek":"Οἱ ἀσθενεῖς ἔφαγον, εἶτα ἀνέστησαν καὶ ἐπορεύοντο. οὐ λόγος μόνον αὐτοὺς ἔσωσεν. τροφῆς γὰρ ἐδέοντο. ἐνταῦθα ἡ ἐπιμέλεια τοῖς φίλοις κέρδος ἔφερεν. Ἐν τῇ ἀσκήσει συγκρίνομεν· οἱ ἄνδρες ἀνέστησαν· μετὰ τὸ φαγεῖν δυνατὸν ἦν ἀναστῆναι· ἀναστάντες ἐπορεύοντο.","gloss":[{"greek":"ἔφαγον","english":"ate; thematic aorist"},{"greek":"ἀνέστησαν","english":"got up; athematic aorist"},{"greek":"τροφῆς","english":"nourishment; genitive"},{"greek":"ἐδέοντο","english":"needed"},{"greek":"ἡ ἐπιμέλεια","english":"care"},{"greek":"κέρδος","english":"benefit"},{"greek":"μετὰ τὸ φαγεῖν","english":"after eating; articulated aorist infinitive"},{"greek":"ἀναστῆναι","english":"to get up; athematic aorist infinitive of ἀνίστημι"},{"greek":"ἀναστάντες","english":"having got up; athematic aorist active participle, nominative masculine plural"}]}],"translation":"The Greeks were marching through Armenia. There was much snow, and the cold was severe. The soldiers and pack animals struggled; not all endured the hardship.\n\nMany of the pack animals died, and people died too. Not only soldiers but also enslaved people were in the snow. The hardship was shared, but their strength was not equal.\n\nThose who arrived first were keeping a fire burning. Those who came later approached the fire. The first arrivals demanded food and only then admitted the others.\n\nOn the next day the men were marching again. Some fell and remained behind. Xenophon stopped beside the weak men; he did not immediately recognize their condition.\n\nA man recognized the condition and told Xenophon. Xenophon went to the pack animals and looked for food. Those who were strong carried the food to the weak.\n\nThe weak men ate, then got up and continued marching. Words alone did not save them. For they needed nourishment. Here care brought benefit to their companions. In the exercise we compare: the men got up; after eating it was possible to get up; having got up, they continued marching.\n","sourceCitation":"Xenophon, Anabasis 4.5.3–9. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1170/1170-h/1170-h.htm https://en.wikipedia.org/wiki/Anabasis_(Xenophon) https://en.wikisource.org/wiki/Anabasis_(Dakyns)/Book_4/Chapter_5","notesMarkdown":"The snow, unequal access to fires, hunger-collapse, and distribution of food follow Xenophon. The compact sequence and closing judgment are adapted. A soldier’s command in the grammar workshop is invented practice, not a quotation."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-29' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 29 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit29$;
DO $audit31$
DECLARE
  old_reading jsonb := $old${"title":"Ἡ Πάνθεια οὐ πείθεται","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Cyropaedia 5.1.2–18 and 6.1.31–36. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The core events follow Xenophon’s literary account of Cyrus the Great. Present and imperfect forms replace some original tense constructions. Panthea’s refusal and appeal remain central. The reflective questions are the course’s, not quotations.","Ask who acts and who is affected: a passive subject is not necessarily a person without agency."],"paragraphs":[{"greek":"Ἡ Πάνθεια αἰχμάλωτός ἐστιν. ὁ Ἄρασπας ὑπὸ τοῦ Κύρου φύλαξ αὐτῆς τάττεται. ἡ γυνὴ ὑπὸ τούτου ἐφυλάττετο. οὗτος ὁ Κῦρος οὐχ ὁ τῶν Ἑλλήνων φίλος ἐν τῇ Ἀναβάσει ἐστίν, ἀλλὰ ὁ παλαιὸς βασιλεύς.","gloss":[{"greek":"αἰχμάλωτός","english":"captive"},{"greek":"ὁ Ἄρασπας","english":"Araspas"},{"greek":"ὑπὸ τοῦ Κύρου","english":"by Cyrus; agent"},{"greek":"φύλαξ","english":"guardian"},{"greek":"τάττεται","english":"is appointed; passive"},{"greek":"ἐφυλάττετο","english":"was guarded; imperfect passive"},{"greek":"ὁ παλαιὸς βασιλεύς","english":"the earlier king"}]},{"greek":"Ὁ Ἄρασπας ἑαυτῷ πιστεύει. τῶν ἐπιθυμιῶν κρατεῖν νομίζει. ὁ δὲ Κῦρος οὐχ οὕτως ἑαυτῷ πιστεύει καὶ τὴν καλὴν γυναῖκα ἰδεῖν οὐ βούλεται.","gloss":[{"greek":"ἑαυτῷ","english":"himself; dative with πιστεύω"},{"greek":"κρατεῖν","english":"to master; genitive object"},{"greek":"νομίζει","english":"thinks"},{"greek":"ἰδεῖν","english":"to see; aorist infinitive"},{"greek":"βούλεται","english":"wishes"}]},{"greek":"Ὁ χρόνος προχωρεῖ· ὁ δὲ Ἄρασπας τῆς γυναικὸς ἐρᾷ. αὐτῇ λόγους προσφέρει. ἡ δὲ Πάνθεια οὐ πείθεται· τὸν ἑαυτῆς ἄνδρα φιλεῖ καὶ τὴν ἀδικίαν οὐ δέχεται.","gloss":[{"greek":"ἐρᾷ","english":"desires, is in love with; takes genitive"},{"greek":"προσφέρει","english":"offers"},{"greek":"οὐ πείθεται","english":"is not persuaded"},{"greek":"ἑαυτῆς","english":"her own"},{"greek":"τὴν ἀδικίαν","english":"wrongdoing"}]},{"greek":"Ἡ γυνὴ ὑπὸ τοῦ φύλακος ἀπειλαῖς φοβεῖται. ὁ Ἄρασπας βίᾳ χρήσεσθαι λέγει. ἡ Πάνθεια οὐ σιωπᾷ· ἄγγελον πρὸς τὸν Κῦρον πέμπει καὶ βοήθειαν ζητεῖ.","gloss":[{"greek":"ὑπὸ τοῦ φύλακος","english":"by the guardian"},{"greek":"ἀπειλαῖς","english":"with threats; means"},{"greek":"φοβεῖται","english":"is frightened"},{"greek":"βίᾳ χρήσεσθαι","english":"to use force; future infinitive in the threat"},{"greek":"ἄγγελον","english":"messenger"}]},{"greek":"Ὁ Κῦρος Ἀρτάβαζον πέμπει. ὁ Ἄρασπας ὑπὸ τοῦ Ἀρταβάζου ἐλέγχεται. ὁ γὰρ φύλαξ τὴν γυναῖκα φυλάττειν ὤφειλεν, οὐ φοβεῖν. νῦν δὲ αὐτὸς αἰσχύνεται.","gloss":[{"greek":"Ἀρτάβαζον","english":"Artabazus"},{"greek":"ἐλέγχεται","english":"is rebuked"},{"greek":"ὤφειλεν","english":"ought; imperfect of ὀφείλω"},{"greek":"φυλάττειν","english":"to protect"},{"greek":"αἰσχύνεται","english":"is ashamed; middle form"}]},{"greek":"Σκόπει τὰς δύο φωνάς· «ὁ φύλαξ τὴν γυναῖκα φοβεῖ» καὶ «ἡ γυνὴ ὑπὸ τοῦ φύλακος φοβεῖται». ὁ αὐτὸς ἄνθρωπος ἀδικεῖ. τὸ δὲ πάθος τῆς γυναικὸς οὐ διὰ τὴν φωνὴν ἀφανὲς γίγνεται.","gloss":[{"greek":"Σκόπει","english":"consider; imperative"},{"greek":"τὰς δύο φωνάς","english":"the two grammatical voices"},{"greek":"ὁ αὐτὸς","english":"the same"},{"greek":"ἀδικεῖ","english":"does wrong"},{"greek":"ἀφανὲς","english":"invisible; supported adjective"}]}],"translation":"Panthea is a captive. Araspas is appointed her guardian by Cyrus. The woman was guarded by him. This Cyrus is not the Greeks’ ally in the Anabasis, but the earlier king.\n\nAraspas trusts himself. He thinks he can master his desires. Cyrus does not trust himself in the same way and does not wish to see the beautiful woman.\n\nTime passes, and Araspas desires the woman. He makes proposals to her. Panthea is not persuaded; she loves her husband and does not accept the wrongdoing.\n\nThe woman is frightened by her guardian’s threats. Araspas says he will use force. Panthea does not remain silent; she sends a messenger to Cyrus and seeks help.\n\nCyrus sends Artabazus. Araspas is rebuked by Artabazus. For the guardian ought to have protected the woman, not frightened her. Now he himself is ashamed.\n\nConsider the two voices: “The guardian frightens the woman” and “The woman is frightened by the guardian.” The same person does wrong. The woman’s suffering does not become invisible because of the grammatical voice.\n","sourceCitation":"Xenophon, Cyropaedia 5.1.2–18 and 6.1.31–36. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/2085/2085-h/2085-h.htm https://en.wikipedia.org/wiki/Cyropaedia https://heritageinstitute.com/zoroastrianism/reference/xenophon/cyropaedia/cyropaedia6.htm https://heritageinstitute.com/zoroastrianism/reference/xenophon/cyropaedia/cyropaedia5.htm","notesMarkdown":"The core events follow Xenophon’s literary account of Cyrus the Great. Present and imperfect forms replace some original tense constructions. Panthea’s refusal and appeal remain central. The reflective questions are the course’s, not quotations."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ἡ Πάνθεια οὐ πείθεται","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Cyropaedia 5.1.2–18 and 6.1.31–36. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The core events follow Xenophon’s literary account of Cyrus the Great. Present and imperfect forms replace some original tense constructions. Panthea’s refusal and appeal remain central. The reflective questions are the course’s, not quotations.","Ask who acts and who is affected: a passive subject is not necessarily a person without agency."],"paragraphs":[{"greek":"Ἡ Πάνθεια αἰχμάλωτός ἐστιν. ὁ Ἄρασπας ὑπὸ τοῦ Κύρου φύλαξ αὐτῆς τάττεται. ἡ γυνὴ ὑπὸ τούτου ἐφυλάττετο. οὗτος ὁ Κῦρος οὐχ ὁ τῶν Ἑλλήνων φίλος ἐν τῇ Ἀναβάσει ἐστίν, ἀλλὰ ὁ παλαιὸς βασιλεύς.","gloss":[{"greek":"αἰχμάλωτός","english":"captive"},{"greek":"ὁ Ἄρασπας","english":"Araspas"},{"greek":"ὑπὸ τοῦ Κύρου","english":"by Cyrus; agent"},{"greek":"φύλαξ","english":"guardian"},{"greek":"τάττεται","english":"is appointed; passive"},{"greek":"ἐφυλάττετο","english":"was guarded; imperfect passive"},{"greek":"ὁ παλαιὸς βασιλεύς","english":"the earlier king"}]},{"greek":"Ὁ Ἄρασπας ἑαυτῷ πιστεύει. τῶν ἐπιθυμιῶν κρατεῖν νομίζει. ὁ δὲ Κῦρος οὐχ οὕτως ἑαυτῷ πιστεύει καὶ τὴν καλὴν γυναῖκα ἰδεῖν οὐ βούλεται.","gloss":[{"greek":"ἑαυτῷ","english":"himself; dative with πιστεύω"},{"greek":"κρατεῖν","english":"to master; genitive object"},{"greek":"νομίζει","english":"thinks"},{"greek":"ἰδεῖν","english":"to see; aorist infinitive"},{"greek":"βούλεται","english":"wishes"}]},{"greek":"Ὁ χρόνος προχωρεῖ· ὁ δὲ Ἄρασπας τῆς γυναικὸς ἐρᾷ. αὐτῇ λόγους προσφέρει. ἡ δὲ Πάνθεια οὐ πείθεται· τὸν ἑαυτῆς ἄνδρα φιλεῖ καὶ τὴν ἀδικίαν οὐ δέχεται.","gloss":[{"greek":"ἐρᾷ","english":"desires, is in love with; takes genitive"},{"greek":"προσφέρει","english":"offers"},{"greek":"οὐ πείθεται","english":"is not persuaded"},{"greek":"ἑαυτῆς","english":"her own"},{"greek":"τὴν ἀδικίαν","english":"wrongdoing"}]},{"greek":"Ἡ γυνὴ ὑπὸ τοῦ φύλακος ἀπειλαῖς φοβεῖται. ὁ Ἄρασπας βίᾳ χρήσεσθαι λέγει. ἡ Πάνθεια οὐ σιωπᾷ· ἄγγελον πρὸς τὸν Κῦρον πέμπει καὶ βοήθειαν ζητεῖ.","gloss":[{"greek":"ὑπὸ τοῦ φύλακος","english":"by the guardian"},{"greek":"ἀπειλαῖς","english":"with threats; means"},{"greek":"φοβεῖται","english":"is frightened"},{"greek":"βίᾳ χρήσεσθαι","english":"to use force; future infinitive in the threat"},{"greek":"ἄγγελον","english":"messenger"},{"greek":"βίᾳ χρήσεσθαι λέγει","english":"he says he will use force; χρήσεσθαι is a future infinitive in reported speech, studied in Lesson 40"}]},{"greek":"Ὁ Κῦρος Ἀρτάβαζον πέμπει. ὁ Ἄρασπας ὑπὸ τοῦ Ἀρταβάζου ἐλέγχεται. ὁ γὰρ φύλαξ τὴν γυναῖκα φυλάττειν ὤφειλεν, οὐ φοβεῖν. νῦν δὲ αὐτὸς αἰσχύνεται.","gloss":[{"greek":"Ἀρτάβαζον","english":"Artabazus"},{"greek":"ἐλέγχεται","english":"is rebuked"},{"greek":"ὤφειλεν","english":"ought; imperfect of ὀφείλω"},{"greek":"φυλάττειν","english":"to protect"},{"greek":"αἰσχύνεται","english":"is ashamed; middle form"}]},{"greek":"Σκόπει τὰς δύο φωνάς· «ὁ φύλαξ τὴν γυναῖκα φοβεῖ» καὶ «ἡ γυνὴ ὑπὸ τοῦ φύλακος φοβεῖται». ὁ αὐτὸς ἄνθρωπος ἀδικεῖ. τὸ δὲ πάθος τῆς γυναικὸς οὐ διὰ τὴν φωνὴν ἀφανὲς γίγνεται.","gloss":[{"greek":"Σκόπει","english":"consider; imperative"},{"greek":"τὰς δύο φωνάς","english":"the two grammatical voices"},{"greek":"ὁ αὐτὸς","english":"the same"},{"greek":"ἀδικεῖ","english":"does wrong"},{"greek":"ἀφανὲς","english":"invisible; supported adjective"}]}],"translation":"Panthea is a captive. Araspas is appointed her guardian by Cyrus. The woman was guarded by him. This Cyrus is not the Greeks’ ally in the Anabasis, but the earlier king.\n\nAraspas trusts himself. He thinks he can master his desires. Cyrus does not trust himself in the same way and does not wish to see the beautiful woman.\n\nTime passes, and Araspas desires the woman. He makes proposals to her. Panthea is not persuaded; she loves her husband and does not accept the wrongdoing.\n\nThe woman is frightened by her guardian’s threats. Araspas says he will use force. Panthea does not remain silent; she sends a messenger to Cyrus and seeks help.\n\nCyrus sends Artabazus. Araspas is rebuked by Artabazus. For the guardian ought to have protected the woman, not frightened her. Now he himself is ashamed.\n\nConsider the two voices: “The guardian frightens the woman” and “The woman is frightened by the guardian.” The same person does wrong. The woman’s suffering does not become invisible because of the grammatical voice.\n","sourceCitation":"Xenophon, Cyropaedia 5.1.2–18 and 6.1.31–36. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/2085/2085-h/2085-h.htm https://en.wikipedia.org/wiki/Cyropaedia https://heritageinstitute.com/zoroastrianism/reference/xenophon/cyropaedia/cyropaedia6.htm https://heritageinstitute.com/zoroastrianism/reference/xenophon/cyropaedia/cyropaedia5.htm","notesMarkdown":"The core events follow Xenophon’s literary account of Cyrus the Great. Present and imperfect forms replace some original tense constructions. Panthea’s refusal and appeal remain central. The reflective questions are the course’s, not quotations."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-31' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 31 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
