DO $audit32$
DECLARE
  old_reading jsonb := $old${"title":"Ποῦ κεῖται τὰ σκεύη;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Oeconomicus 8.11–20 and 9.2–10. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","Ischomachus’ ship comparison and household organization are adapted from his report to Socrates. The concise questions about objects are course wording. His wife’s views reach us through a male speaker and author, not an independent transcript.","δύναμαι, κεῖμαι, and ἐπίσταμαι connect ability and knowledge with the practical arrangement of objects."],"paragraphs":[{"greek":"Ὁ Ἰσχόμαχος τῷ Σωκράτει περὶ τῆς οἰκίας λέγει. «ποῦ κεῖται τὰ σκεύη;» οὐ μικρὰ αὕτη ἡ ἐρώτησίς ἐστιν. ὁ γὰρ ζητῶν πολλάκις οὐ δύναται εὑρίσκειν.","gloss":[{"greek":"Ὁ Ἰσχόμαχος","english":"Ischomachus"},{"greek":"κεῖται","english":"lie, are situated; neuter plural subject"},{"greek":"τὰ σκεύη","english":"equipment, objects"},{"greek":"δύναται","english":"is able"},{"greek":"εὑρίσκειν","english":"to find"}]},{"greek":"Ὁ Ἰσχόμαχος ναῦν Φοινικικὴν εἶδεν. ἐν τῇ νηὶ πολλὰ σκεύη ἔκειτο· ἕκαστον δὲ τὴν ἑαυτοῦ χώραν εἶχεν. ὁ τῶν σκευῶν φύλαξ ἠπίστατο τὰς χώρας.","gloss":[{"greek":"ναῦν Φοινικικὴν","english":"a Phoenician ship"},{"greek":"ἐν τῇ νηὶ","english":"in the ship"},{"greek":"ἔκειτο","english":"lay; imperfect"},{"greek":"ἕκαστον","english":"each item"},{"greek":"χώραν","english":"place"},{"greek":"ἠπίστατο","english":"knew; imperfect"}]},{"greek":"Ἡ ναῦς ἐν τῇ θαλάττῃ κινεῖται. ὅμως δὲ οἱ ναῦται τὰ χρήσιμα λαβεῖν δύνανται. ἡ δὲ οἰκία μένει· τί οὖν κωλύει καὶ ἐνθάδε τάξιν εἶναι;","gloss":[{"greek":"κινεῖται","english":"moves; middle/passive"},{"greek":"οἱ ναῦται","english":"sailors"},{"greek":"λαβεῖν","english":"to get; aorist infinitive"},{"greek":"δύνανται","english":"are able"},{"greek":"κωλύει","english":"prevents"},{"greek":"τάξιν","english":"order"}]},{"greek":"Ἡ γυνὴ τὴν τάξιν ζητεῖ. ὁ Ἰσχόμαχος τὰ οἰκήματα αὐτῇ δεικνύει. ὁ μὲν σῖτος ἐν ξηρῷ κεῖται, ὁ δὲ οἶνος ἐν ψυχρῷ. τὰ δὲ ἱμάτια ἄλλην χώραν ἔχει.","gloss":[{"greek":"Ἡ γυνὴ","english":"his wife"},{"greek":"οἰκήματα","english":"rooms"},{"greek":"δεικνύει","english":"shows; supported verb"},{"greek":"ξηρῷ","english":"dry place; substantival adjective"},{"greek":"ψυχρῷ","english":"cool place"},{"greek":"ἱμάτια","english":"clothes"}]},{"greek":"Οἱ ἐν τῇ οἰκίᾳ οὐ πάντες τὰ αὐτὰ ἐπίστανται. ἡ μὲν γυνὴ τὰ ἔργα σκοπεῖ, οἱ δὲ δοῦλοι πονοῦσιν. ἡ τάξις καὶ μνήμης καὶ ἐργασίας δεῖται.","gloss":[{"greek":"τὰ αὐτὰ","english":"the same things"},{"greek":"ἐπίστανται","english":"know"},{"greek":"σκοπεῖ","english":"oversees"},{"greek":"δοῦλοι","english":"enslaved workers"},{"greek":"μνήμης","english":"memory; genitive"},{"greek":"δεῖται","english":"needs; takes genitive"}]},{"greek":"Νῦν ἡμεῖς τὴν τάξιν ἐξετάζομεν. τίς εὑρίσκει τὰ σκεύη; τίς αὐτὰ κομίζει; τίς κελεύει; τὸ «δύναμαι» καὶ τὸ «ἐπίσταμαι» οὐ τὸ αὐτὸ δηλοῖ.","gloss":[{"greek":"ἡμεῖς","english":"we"},{"greek":"ἐξετάζομεν","english":"examine"},{"greek":"κομίζει","english":"carries"},{"greek":"κελεύει","english":"gives orders"},{"greek":"δηλοῖ","english":"makes clear, means"}]}],"translation":"Ischomachus speaks with Socrates about the household. “Where are the objects?” This is not a small question. For someone searching often cannot find them.\n\nIschomachus saw a Phoenician ship. Much equipment lay in the ship, and each item had its own place. The keeper of the equipment knew the places.\n\nThe ship moves on the sea. Nevertheless the sailors can get useful things. But the house stays still; what then prevents order here too?\n\nHis wife asks for the arrangement. Ischomachus shows her the rooms. Grain lies in a dry place, wine in a cool place. Clothing has another place.\n\nNot everyone in the house knows the same things. The wife oversees the work, while enslaved workers labor. Order requires both memory and work.\n\nNow we examine the arrangement. Who finds the objects? Who carries them? Who gives orders? “I am able” and “I know how” do not mean the same thing.\n","sourceCitation":"Xenophon, Oeconomicus 8.11–20 and 9.2–10. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1173/1173-h/1173-h.htm https://en.wikipedia.org/wiki/Oeconomicus https://www.gutenberg.org/files/1173/1173-h/1173-h.htm","notesMarkdown":"Ischomachus’ ship comparison and household organization are adapted from his report to Socrates. The concise questions about objects are course wording. His wife’s views reach us through a male speaker and author, not an independent transcript."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ποῦ κεῖται τὰ σκεύη;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Oeconomicus 8.11–20 and 9.2–10. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","Ischomachus’ ship comparison and household organization are adapted from his report to Socrates. The concise questions about objects are course wording. His wife’s views reach us through a male speaker and author, not an independent transcript.","δύναμαι, κεῖμαι, and ἐπίσταμαι connect ability and knowledge with the practical arrangement of objects."],"paragraphs":[{"greek":"Ὁ Ἰσχόμαχος τῷ Σωκράτει περὶ τῆς οἰκίας λέγει. «ποῦ κεῖται τὰ σκεύη;» οὐ μικρὰ αὕτη ἡ ἐρώτησίς ἐστιν. ὁ γὰρ ζητῶν πολλάκις οὐ δύναται εὑρίσκειν.","gloss":[{"greek":"Ὁ Ἰσχόμαχος","english":"Ischomachus"},{"greek":"κεῖται","english":"lie, are situated; neuter plural subject"},{"greek":"τὰ σκεύη","english":"equipment, objects"},{"greek":"δύναται","english":"is able"},{"greek":"εὑρίσκειν","english":"to find"}]},{"greek":"Ὁ Ἰσχόμαχος ναῦν Φοινικικὴν εἶδεν. ἐν τῇ νηὶ πολλὰ σκεύη ἔκειτο· ἕκαστον δὲ τὴν ἑαυτοῦ χώραν εἶχεν. ὁ τῶν σκευῶν φύλαξ ἠπίστατο τὰς χώρας. Ὁ μὲν φύλαξ ἠπίστατο τὰ σκεύη εὑρίσκειν, οἱ δὲ ναῦται καὶ ἐν χαλεπῇ θαλάττῃ ἐδύναντο αὐτὰ λαμβάνειν.","gloss":[{"greek":"ναῦν Φοινικικὴν","english":"a Phoenician ship"},{"greek":"ἐν τῇ νηὶ","english":"in the ship"},{"greek":"ἔκειτο","english":"lay; imperfect"},{"greek":"ἕκαστον","english":"each item"},{"greek":"χώραν","english":"place"},{"greek":"ἠπίστατο","english":"knew; imperfect"},{"greek":"ἠπίστατο τὰ σκεύη εὑρίσκειν","english":"knew how to find; imperfect of ἐπίσταμαι with infinitive"},{"greek":"ἐδύναντο αὐτὰ λαμβάνειν","english":"were able to retrieve; imperfect of δύναμαι with infinitive"}]},{"greek":"Ἡ ναῦς ἐν τῇ θαλάττῃ κινεῖται. ὅμως δὲ οἱ ναῦται τὰ χρήσιμα λαβεῖν δύνανται. ἡ δὲ οἰκία μένει· τί οὖν κωλύει καὶ ἐνθάδε τάξιν εἶναι;","gloss":[{"greek":"κινεῖται","english":"moves; middle/passive"},{"greek":"οἱ ναῦται","english":"sailors"},{"greek":"λαβεῖν","english":"to get; aorist infinitive"},{"greek":"δύνανται","english":"are able"},{"greek":"κωλύει","english":"prevents"},{"greek":"τάξιν","english":"order"}]},{"greek":"Ἡ γυνὴ τὴν τάξιν ζητεῖ. ὁ Ἰσχόμαχος τὰ οἰκήματα αὐτῇ δεικνύει. ὁ μὲν σῖτος ἐν ξηρῷ κεῖται, ὁ δὲ οἶνος ἐν ψυχρῷ. τὰ δὲ ἱμάτια ἄλλην χώραν ἔχει.","gloss":[{"greek":"Ἡ γυνὴ","english":"his wife"},{"greek":"οἰκήματα","english":"rooms"},{"greek":"δεικνύει","english":"shows; present active of δείκνυμι; supported reading form before Lesson 36"},{"greek":"ξηρῷ","english":"dry place; substantival adjective"},{"greek":"ψυχρῷ","english":"cool place"},{"greek":"ἱμάτια","english":"clothes"}]},{"greek":"Οἱ ἐν τῇ οἰκίᾳ οὐ πάντες τὰ αὐτὰ ἐπίστανται. ἡ μὲν γυνὴ τὰ ἔργα σκοπεῖ, οἱ δὲ δοῦλοι πονοῦσιν. ἡ τάξις καὶ μνήμης καὶ ἐργασίας δεῖται.","gloss":[{"greek":"τὰ αὐτὰ","english":"the same things"},{"greek":"ἐπίστανται","english":"know"},{"greek":"σκοπεῖ","english":"oversees"},{"greek":"δοῦλοι","english":"enslaved workers"},{"greek":"μνήμης","english":"memory; genitive"},{"greek":"δεῖται","english":"needs; takes genitive"}]},{"greek":"Νῦν ἡμεῖς τὴν τάξιν ἐξετάζομεν. τίς εὑρίσκει τὰ σκεύη; τίς αὐτὰ κομίζει; τίς κελεύει; τὸ «δύναμαι» καὶ τὸ «ἐπίσταμαι» οὐ τὸ αὐτὸ δηλοῖ.","gloss":[{"greek":"ἡμεῖς","english":"we"},{"greek":"ἐξετάζομεν","english":"examine"},{"greek":"κομίζει","english":"carries"},{"greek":"κελεύει","english":"gives orders"},{"greek":"δηλοῖ","english":"makes clear, means"}]}],"translation":"Ischomachus speaks with Socrates about the household. “Where are the objects?” This is not a small question. For someone searching often cannot find them.\n\nIschomachus saw a Phoenician ship. Much equipment lay in the ship, and each item had its own place. The keeper of the equipment knew the places. The keeper knew how to find the equipment, and the sailors could retrieve it even in rough seas.\n\nThe ship moves on the sea. Nevertheless the sailors can get useful things. But the house stays still; what then prevents order here too?\n\nHis wife asks for the arrangement. Ischomachus shows her the rooms. Grain lies in a dry place, wine in a cool place. Clothing has another place.\n\nNot everyone in the house knows the same things. The wife oversees the work, while enslaved workers labor. Order requires both memory and work.\n\nNow we examine the arrangement. Who finds the objects? Who carries them? Who gives orders? “I am able” and “I know how” do not mean the same thing.\n","sourceCitation":"Xenophon, Oeconomicus 8.11–20 and 9.2–10. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1173/1173-h/1173-h.htm https://en.wikipedia.org/wiki/Oeconomicus https://www.gutenberg.org/files/1173/1173-h/1173-h.htm","notesMarkdown":"Ischomachus’ ship comparison and household organization are adapted from his report to Socrates. The concise questions about objects are course wording. His wife’s views reach us through a male speaker and author, not an independent transcript."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-32' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 32 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
