DO $audit34$
DECLARE
  old_reading jsonb := $old${"title":"Μέτρον ἐν τῷ συμποσίῳ","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Symposium 2.24–27. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The comparison of wine to water nourishing plants follows Socrates in the Symposium. The serving instructions and -μι practice sentences are reconstructed teaching dialogue, not a transcript. The lesson title is a traditional maxim, not a quotation assigned here to Xenophon.","Notice δίδωμι and τίθημι: what is given, what is placed, and who receives it?"],"paragraphs":[{"greek":"Ὁ Καλλίας τοὺς φίλους ἐπὶ δεῖπνον καλεῖ. μετὰ δὲ τὸ δεῖπνον οἱ φίλοι πίνουσι καὶ διαλέγονται. ὁ Σωκράτης πάρεστιν· οὐ σιωπᾷ, ἀλλὰ περὶ τοῦ οἴνου λέγει.","gloss":[{"greek":"Ὁ Καλλίας","english":"Callias"},{"greek":"ἐπὶ δεῖπνον","english":"to dinner"},{"greek":"μετὰ δὲ τὸ δεῖπνον","english":"after dinner"},{"greek":"πάρεστιν","english":"is present"},{"greek":"σιωπᾷ","english":"remains silent"}]},{"greek":"Ὁ οἶνος ἡδονὴν δίδωσιν, ἀλλὰ τὸ πολὺ βλάπτει. ὁ Σωκράτης τὰ φυτὰ παράδειγμα τίθησιν. ὀλίγον ὕδωρ τὰ φυτὰ αὔξει· τὸ δὲ πολὺ ὕδωρ κακὸν παρέχει.","gloss":[{"greek":"δίδωσιν","english":"gives; present of δίδωμι"},{"greek":"τὸ πολὺ","english":"excess, too much"},{"greek":"τὰ φυτὰ","english":"plants"},{"greek":"τίθησιν","english":"sets out; present of τίθημι"},{"greek":"αὔξει","english":"makes grow"}]},{"greek":"Καὶ οἱ ἄνθρωποι μέτρου δέονται. ὁ Σωκράτης οὐ κελεύει πάντας πολὺ πίνειν. μικρὰ ποτήρια καὶ πολλάκις· οὕτως οἱ φίλοι ἡδέως τὴν ἑσπέραν διάγουσιν.","gloss":[{"greek":"μέτρου δέονται","english":"need measure; genitive"},{"greek":"μικρὰ ποτήρια","english":"small cups"},{"greek":"πολλάκις","english":"frequently"},{"greek":"ἡδέως","english":"pleasantly"},{"greek":"τὴν ἑσπέραν","english":"the evening"},{"greek":"διάγουσιν","english":"spend"}]},{"greek":"Ἐν τῷ ἡμετέρῳ παραδείγματι ὁ φίλος λέγει· «δὸς τὸ ποτήριον, θὲς δὲ τὸν κρατῆρα ἐν μέσῳ.» ὁ ἕτερος τὸ ποτήριον δίδωσι καὶ τὸν κρατῆρα τίθησιν.","gloss":[{"greek":"Ἐν τῷ ἡμετέρῳ παραδείγματι","english":"in our teaching example"},{"greek":"δὸς","english":"give; aorist imperative"},{"greek":"θὲς","english":"put; aorist imperative"},{"greek":"τὸν κρατῆρα","english":"the mixing bowl"},{"greek":"ἐν μέσῳ","english":"in the middle"}]},{"greek":"Ἔδοσαν μὲν τὸν οἶνον, ἔθεσαν δὲ τὰ ποτήρια. νῦν οἱ συμπόται λόγους ἀντὶ κραυγῆς ἀκούουσιν. ἡ τῶν φίλων συνουσία οὐ τῷ πλήθει τοῦ οἴνου μόνον κρίνεται.","gloss":[{"greek":"Ἔδοσαν","english":"they gave; aorist"},{"greek":"ἔθεσαν","english":"they placed; aorist"},{"greek":"οἱ συμπόται","english":"fellow drinkers"},{"greek":"ἀντὶ κραυγῆς","english":"instead of shouting"},{"greek":"τῷ πλήθει","english":"by the quantity"},{"greek":"κρίνεται","english":"is judged"}]},{"greek":"Τί δίδομεν τοῖς φίλοις; τί τίθεμεν ἐν μέσῳ; οὐ ποτὸν μόνον, ἀλλὰ καὶ λόγον καὶ προσοχήν. ὁ δὲ τοῦ σώματος κύριος καὶ τοῦ ἄλλου ἀκούει.","gloss":[{"greek":"δίδομεν","english":"we give"},{"greek":"τίθεμεν","english":"we place"},{"greek":"προσοχήν","english":"attention"},{"greek":"τοῦ σώματος","english":"of the body"},{"greek":"κύριος","english":"master, in command"}]}],"translation":"Callias invites friends to dinner. After dinner the friends drink and converse. Socrates is present; he does not remain silent but speaks about wine.\n\nWine gives pleasure, but excess harms. Socrates sets out plants as an example. A little water makes plants grow; too much water causes harm.\n\nPeople too need measure. Socrates does not urge everyone to drink a great deal. Small cups, and frequently: in this way the friends spend the evening pleasantly.\n\nIn our teaching example the friend says, “Give the cup, and put the mixing bowl in the middle.” The other gives the cup and places the mixing bowl.\n\nThey gave the wine and placed the cups. Now the fellow drinkers hear conversation instead of shouting. The gathering of friends is not judged by the quantity of wine alone.\n\nWhat do we give our friends? What do we place in the middle? Not only drink, but also conversation and attention. The person in command of his body also listens to the other person.\n","sourceCitation":"Xenophon, Symposium 2.24–27. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1181/1181-h/1181-h.htm https://en.wikipedia.org/wiki/Symposium_(Xenophon) https://www.perseus.tufts.edu/hopper/text?doc=Xen.+Sym.+2&lang=original https://www.metmuseum.org/art/collection/search/253349","notesMarkdown":"The comparison of wine to water nourishing plants follows Socrates in the Symposium. The serving instructions and -μι practice sentences are reconstructed teaching dialogue, not a transcript. The lesson title is a traditional maxim, not a quotation assigned here to Xenophon."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Μέτρον ἐν τῷ συμποσίῳ","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Symposium 2.24–27. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The comparison of wine to water nourishing plants follows Socrates in the Symposium. The serving instructions and -μι practice sentences are reconstructed teaching dialogue, not a transcript. The lesson title is a traditional maxim, not a quotation assigned here to Xenophon.","Notice δίδωμι and τίθημι: what is given, what is placed, and who receives it?"],"paragraphs":[{"greek":"Ὁ Καλλίας τοὺς φίλους ἐπὶ δεῖπνον καλεῖ. μετὰ δὲ τὸ δεῖπνον οἱ φίλοι πίνουσι καὶ διαλέγονται. ὁ Σωκράτης πάρεστιν· οὐ σιωπᾷ, ἀλλὰ περὶ τοῦ οἴνου λέγει.","gloss":[{"greek":"Ὁ Καλλίας","english":"Callias"},{"greek":"ἐπὶ δεῖπνον","english":"to dinner"},{"greek":"μετὰ δὲ τὸ δεῖπνον","english":"after dinner"},{"greek":"πάρεστιν","english":"is present"},{"greek":"σιωπᾷ","english":"remains silent"}]},{"greek":"Ὁ οἶνος ἡδονὴν δίδωσιν, ἀλλὰ τὸ πολὺ βλάπτει. ὁ Σωκράτης τὰ φυτὰ παράδειγμα τίθησιν. ὀλίγον ὕδωρ τὰ φυτὰ αὔξει· τὸ δὲ πολὺ ὕδωρ κακὸν παρέχει.","gloss":[{"greek":"δίδωσιν","english":"gives; present of δίδωμι"},{"greek":"τὸ πολὺ","english":"excess, too much"},{"greek":"τὰ φυτὰ","english":"plants"},{"greek":"τίθησιν","english":"sets out; present of τίθημι"},{"greek":"αὔξει","english":"makes grow"}]},{"greek":"Καὶ οἱ ἄνθρωποι μέτρου δέονται. ὁ Σωκράτης οὐ κελεύει πάντας πολὺ πίνειν. μικρὰ ποτήρια καὶ πολλάκις· οὕτως οἱ φίλοι ἡδέως τὴν ἑσπέραν διάγουσιν.","gloss":[{"greek":"μέτρου δέονται","english":"need measure; genitive"},{"greek":"μικρὰ ποτήρια","english":"small cups"},{"greek":"πολλάκις","english":"frequently"},{"greek":"ἡδέως","english":"pleasantly"},{"greek":"τὴν ἑσπέραν","english":"the evening"},{"greek":"διάγουσιν","english":"spend"}]},{"greek":"Ἐν τῷ ἡμετέρῳ παραδείγματι ὁ φίλος λέγει· «δὸς τὸ ποτήριον, θὲς δὲ τὸν κρατῆρα ἐν μέσῳ.» ὁ ἕτερος τὸ ποτήριον δίδωσι καὶ τὸν κρατῆρα τίθησιν. Ὁ οἰνοχόος πολλάκις ἐδίδου τὰ ποτήρια καὶ ἐτίθει αὐτὰ παρὰ τοῖς συμπόταις· ἔπειτα ἓν ποτήριον ἔδωκε καὶ ἔθηκε.","gloss":[{"greek":"Ἐν τῷ ἡμετέρῳ παραδείγματι","english":"in our teaching example"},{"greek":"δὸς","english":"give; aorist imperative"},{"greek":"θὲς","english":"put; aorist imperative"},{"greek":"τὸν κρατῆρα","english":"the mixing bowl"},{"greek":"ἐν μέσῳ","english":"in the middle"},{"greek":"Ὁ οἰνοχόος","english":"the cupbearer"},{"greek":"ἐδίδου","english":"was giving; imperfect of δίδωμι"},{"greek":"ἐτίθει","english":"was setting down; imperfect of τίθημι"},{"greek":"ἔδωκε","english":"gave; aorist of δίδωμι"},{"greek":"ἔθηκε","english":"set down; aorist of τίθημι"}]},{"greek":"Ἔδοσαν μὲν τὸν οἶνον, ἔθεσαν δὲ τὰ ποτήρια. νῦν οἱ συμπόται λόγους ἀντὶ κραυγῆς ἀκούουσιν. ἡ τῶν φίλων συνουσία οὐ τῷ πλήθει τοῦ οἴνου μόνον κρίνεται.","gloss":[{"greek":"Ἔδοσαν","english":"they gave; aorist"},{"greek":"ἔθεσαν","english":"they placed; aorist"},{"greek":"οἱ συμπόται","english":"fellow drinkers"},{"greek":"ἀντὶ κραυγῆς","english":"instead of shouting"},{"greek":"τῷ πλήθει","english":"by the quantity"},{"greek":"κρίνεται","english":"is judged"}]},{"greek":"Τί δίδομεν τοῖς φίλοις; τί τίθεμεν ἐν μέσῳ; οὐ ποτὸν μόνον, ἀλλὰ καὶ λόγον καὶ προσοχήν. ὁ δὲ τοῦ σώματος κύριος καὶ τοῦ ἄλλου ἀκούει.","gloss":[{"greek":"δίδομεν","english":"we give"},{"greek":"τίθεμεν","english":"we place"},{"greek":"προσοχήν","english":"attention"},{"greek":"τοῦ σώματος","english":"of the body"},{"greek":"κύριος","english":"master, in command"}]}],"translation":"Callias invites friends to dinner. After dinner the friends drink and converse. Socrates is present; he does not remain silent but speaks about wine.\n\nWine gives pleasure, but excess harms. Socrates sets out plants as an example. A little water makes plants grow; too much water causes harm.\n\nPeople too need measure. Socrates does not urge everyone to drink a great deal. Small cups, and frequently: in this way the friends spend the evening pleasantly.\n\nIn our teaching example the friend says, “Give the cup, and put the mixing bowl in the middle.” The other gives the cup and places the mixing bowl. The cupbearer repeatedly handed out the cups and set them beside the guests; then he gave and set down one cup.\n\nThey gave the wine and placed the cups. Now the fellow drinkers hear conversation instead of shouting. The gathering of friends is not judged by the quantity of wine alone.\n\nWhat do we give our friends? What do we place in the middle? Not only drink, but also conversation and attention. The person in command of his body also listens to the other person.\n","sourceCitation":"Xenophon, Symposium 2.24–27. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1181/1181-h/1181-h.htm https://en.wikipedia.org/wiki/Symposium_(Xenophon) https://www.perseus.tufts.edu/hopper/text?doc=Xen.+Sym.+2&lang=original https://www.metmuseum.org/art/collection/search/253349","notesMarkdown":"The comparison of wine to water nourishing plants follows Socrates in the Symposium. The serving instructions and -μι practice sentences are reconstructed teaching dialogue, not a transcript. The lesson title is a traditional maxim, not a quotation assigned here to Xenophon."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-34' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 34 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
