DO $audit35$
DECLARE
  old_reading jsonb := $old${"title":"Τί ἐστιν ἐγκράτεια;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 3.9.4–5 and 4.5.1–12. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The argument about knowledge, conduct, freedom, and appetite follows these two passages. Their combination, setting, and the -μι examples are newly composed; Xenophon does not stage this as one continuous conversation.","Use genitive absolutes to identify background circumstances; distinguish causing someone to stand from standing oneself."],"paragraphs":[{"greek":"Τοῦ Σωκράτους λέγοντος, οἱ φίλοι ἤκουον. ὁ δὲ περὶ σοφίας καὶ σωφροσύνης ἔλεγεν. οὐκ ἀρκεῖ τὸ ἀγαθὸν εἰδέναι καὶ τὸ κακὸν πράττειν.","gloss":[{"greek":"Τοῦ Σωκράτους λέγοντος","english":"while Socrates was speaking; genitive absolute"},{"greek":"σωφροσύνης","english":"sound self-control"},{"greek":"ἀρκεῖ","english":"is enough"},{"greek":"εἰδέναι","english":"to know; perfect infinitive with present sense"},{"greek":"τὸ κακὸν","english":"what is bad"}]},{"greek":"Ὁ Σωκράτης ἐρωτᾷ περὶ ἐλευθερίας. τῶν ἐπιθυμιῶν ἀρχουσῶν, ὁ ἄνθρωπος κύριος ἑαυτοῦ ἐστιν; ὁ γὰρ τῆς ἡδονῆς δοῦλος πολλάκις τὸ βέλτιστον οὐ πράττει.","gloss":[{"greek":"ἐλευθερίας","english":"freedom"},{"greek":"τῶν ἐπιθυμιῶν ἀρχουσῶν","english":"when desires rule; genitive absolute"},{"greek":"ἑαυτοῦ","english":"of himself"},{"greek":"δοῦλος","english":"slave; metaphor here"},{"greek":"τὸ βέλτιστον","english":"what is best"}]},{"greek":"Ὁ ἐγκρατὴς καὶ μανθάνειν δύναται καὶ τοῖς φίλοις βοηθεῖν. οὐ πᾶσαν ἡδονὴν ἀφαιρεῖται· τὴν δὲ ὥραν καὶ τὸ μέτρον σκοπεῖ. οὕτως ὁ λόγος πρὸς τὸν βίον ἄγει.","gloss":[{"greek":"Ὁ ἐγκρατὴς","english":"the self-controlled person"},{"greek":"μανθάνειν","english":"to learn"},{"greek":"ἀφαιρεῖται","english":"takes away; middle"},{"greek":"ὥραν","english":"the right time"},{"greek":"σκοπεῖ","english":"considers"}]},{"greek":"Ἐν παραδείγματι ὁ διδάσκαλος τὸν παῖδα ἵστησιν. ὁ δὲ παῖς ἔστη καὶ ἤκουσεν. τοῦ λόγου παυσαμένου, ὁ παῖς ἀπῆλθεν. οὐχ ὁ αὐτὸς τὰ πάντα πράττει.","gloss":[{"greek":"Ἐν παραδείγματι","english":"in a teaching example"},{"greek":"ἵστησιν","english":"makes stand; transitive present"},{"greek":"ἔστη","english":"stood; intransitive second aorist"},{"greek":"τοῦ λόγου παυσαμένου","english":"when the speech ended; genitive absolute"},{"greek":"ἀπῆλθεν","english":"went away"}]},{"greek":"Ἄλλο παράδειγμα· οἱ πολῖται τὸν ἄνδρα ἄρχοντα καθιστᾶσιν. ἐκεῖνος δὲ ἀπέστη τῆς ἀρχῆς. οἱ πολῖται αὐτὸν κατέστησαν· αὐτὸς δὲ ἀπέστη.","gloss":[{"greek":"καθιστᾶσιν","english":"appoint; present of καθίστημι"},{"greek":"ἀπέστη","english":"withdrew; second aorist"},{"greek":"τῆς ἀρχῆς","english":"from office; genitive of separation"},{"greek":"κατέστησαν","english":"appointed; transitive aorist"},{"greek":"αὐτὸς","english":"he himself"}]},{"greek":"Τῶν φίλων ζητούντων, ὁ λόγος οὐ παύεται. ἡ ἐγκράτεια μόνον ἡσυχία ἐστίν, ἢ δύναμις πρὸς τὸ καλῶς πράττειν; τὴν ἀπόκρισιν ἐν τῷ βίῳ καὶ ἐν τοῖς ἔργοις ζητοῦμεν.","gloss":[{"greek":"Τῶν φίλων ζητούντων","english":"while the friends investigate"},{"greek":"ἡσυχία","english":"quietness"},{"greek":"δύναμις","english":"capacity"},{"greek":"πρὸς τὸ καλῶς πράττειν","english":"for acting well"},{"greek":"τὴν ἀπόκρισιν","english":"the answer"}]}],"translation":"While Socrates was speaking, the friends listened. He spoke about wisdom and sound self-control. It is not enough to know the good and do what is bad.\n\nSocrates asks about freedom. When desires rule, is the person master of himself? For the slave of pleasure often fails to do what is best.\n\nThe self-controlled person can both learn and help friends. He does not take away every pleasure; he considers the right time and measure. In this way the argument leads toward life.\n\nIn a teaching example the teacher makes the boy stand. The boy stood and listened. When the speech ended, the boy went away. The same person does not perform every action.\n\nAnother example: the citizens appoint the man ruler. He then withdrew from office. The citizens appointed him, but he himself withdrew.\n\nWhile the friends investigate, the discussion does not stop. Is self-mastery merely quietness, or a capacity to act well? We seek the answer in life and actions.\n","sourceCitation":"Xenophon, Memorabilia 3.9.4–5 and 4.5.1–12. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm https://en.wikipedia.org/wiki/Memorabilia_(Xenophon) https://monadnock.net/xenophon/mem4-5.html https://monadnock.net/xenophon/mem3-9.html","notesMarkdown":"The argument about knowledge, conduct, freedom, and appetite follows these two passages. Their combination, setting, and the -μι examples are newly composed; Xenophon does not stage this as one continuous conversation."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Τί ἐστιν ἐγκράτεια;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 3.9.4–5 and 4.5.1–12. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The argument about knowledge, conduct, freedom, and appetite follows these two passages. Their combination, setting, and the -μι examples are newly composed; Xenophon does not stage this as one continuous conversation.","Use genitive absolutes to identify background circumstances; distinguish causing someone to stand from standing oneself."],"paragraphs":[{"greek":"Τοῦ Σωκράτους λέγοντος, οἱ φίλοι ἤκουον. ὁ δὲ περὶ σοφίας καὶ σωφροσύνης ἔλεγεν. οὐκ ἀρκεῖ τὸ ἀγαθὸν εἰδέναι καὶ τὸ κακὸν πράττειν.","gloss":[{"greek":"Τοῦ Σωκράτους λέγοντος","english":"while Socrates was speaking; genitive absolute"},{"greek":"σωφροσύνης","english":"sound self-control"},{"greek":"ἀρκεῖ","english":"is enough"},{"greek":"εἰδέναι","english":"to know; perfect infinitive of οἶδα with present meaning; supported reading vocabulary"},{"greek":"τὸ κακὸν","english":"what is bad"}]},{"greek":"Ὁ Σωκράτης ἐρωτᾷ περὶ ἐλευθερίας. τῶν ἐπιθυμιῶν ἀρχουσῶν, ὁ ἄνθρωπος κύριος ἑαυτοῦ ἐστιν; ὁ γὰρ τῆς ἡδονῆς δοῦλος πολλάκις τὸ βέλτιστον οὐ πράττει.","gloss":[{"greek":"ἐλευθερίας","english":"freedom"},{"greek":"τῶν ἐπιθυμιῶν ἀρχουσῶν","english":"when desires rule; genitive absolute"},{"greek":"ἑαυτοῦ","english":"of himself"},{"greek":"δοῦλος","english":"slave; metaphor here"},{"greek":"τὸ βέλτιστον","english":"what is best"}]},{"greek":"Ὁ ἐγκρατὴς καὶ μανθάνειν δύναται καὶ τοῖς φίλοις βοηθεῖν. οὐ πᾶσαν ἡδονὴν ἀφαιρεῖται· τὴν δὲ ὥραν καὶ τὸ μέτρον σκοπεῖ. οὕτως ὁ λόγος πρὸς τὸν βίον ἄγει.","gloss":[{"greek":"Ὁ ἐγκρατὴς","english":"the self-controlled person"},{"greek":"μανθάνειν","english":"to learn"},{"greek":"ἀφαιρεῖται","english":"takes away; middle"},{"greek":"ὥραν","english":"the right time"},{"greek":"σκοπεῖ","english":"considers"}]},{"greek":"Ἐν παραδείγματι ὁ διδάσκαλος τὸν παῖδα ἵστησιν. ὁ δὲ παῖς ἔστη καὶ ἤκουσεν. τοῦ λόγου παυσαμένου, ὁ παῖς ἀπῆλθεν. οὐχ ὁ αὐτὸς τὰ πάντα πράττει.","gloss":[{"greek":"Ἐν παραδείγματι","english":"in a teaching example"},{"greek":"ἵστησιν","english":"makes stand; transitive present"},{"greek":"ἔστη","english":"stood; intransitive second aorist"},{"greek":"τοῦ λόγου παυσαμένου","english":"when the speech ended; genitive absolute"},{"greek":"ἀπῆλθεν","english":"went away"}]},{"greek":"Ἄλλο παράδειγμα· οἱ πολῖται τὸν ἄνδρα ἄρχοντα καθιστᾶσιν. ἐκεῖνος δὲ ἀπέστη τῆς ἀρχῆς. οἱ πολῖται αὐτὸν κατέστησαν· αὐτὸς δὲ ἀπέστη.","gloss":[{"greek":"καθιστᾶσιν","english":"appoint; present of καθίστημι"},{"greek":"ἀπέστη","english":"withdrew; second aorist"},{"greek":"τῆς ἀρχῆς","english":"from office; genitive of separation"},{"greek":"κατέστησαν","english":"appointed; transitive aorist"},{"greek":"αὐτὸς","english":"he himself"}]},{"greek":"Τῶν φίλων ζητούντων, ὁ λόγος οὐ παύεται. ἡ ἐγκράτεια μόνον ἡσυχία ἐστίν, ἢ δύναμις πρὸς τὸ καλῶς πράττειν; τὴν ἀπόκρισιν ἐν τῷ βίῳ καὶ ἐν τοῖς ἔργοις ζητοῦμεν.","gloss":[{"greek":"Τῶν φίλων ζητούντων","english":"while the friends investigate"},{"greek":"ἡσυχία","english":"quietness"},{"greek":"δύναμις","english":"capacity"},{"greek":"πρὸς τὸ καλῶς πράττειν","english":"for acting well"},{"greek":"τὴν ἀπόκρισιν","english":"the answer"}]}],"translation":"While Socrates was speaking, the friends listened. He spoke about wisdom and sound self-control. It is not enough to know the good and do what is bad.\n\nSocrates asks about freedom. When desires rule, is the person master of himself? For the slave of pleasure often fails to do what is best.\n\nThe self-controlled person can both learn and help friends. He does not take away every pleasure; he considers the right time and measure. In this way the argument leads toward life.\n\nIn a teaching example the teacher makes the boy stand. The boy stood and listened. When the speech ended, the boy went away. The same person does not perform every action.\n\nAnother example: the citizens appoint the man ruler. He then withdrew from office. The citizens appointed him, but he himself withdrew.\n\nWhile the friends investigate, the discussion does not stop. Is self-mastery merely quietness, or a capacity to act well? We seek the answer in life and actions.\n","sourceCitation":"Xenophon, Memorabilia 3.9.4–5 and 4.5.1–12. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm https://en.wikipedia.org/wiki/Memorabilia_(Xenophon) https://monadnock.net/xenophon/mem4-5.html https://monadnock.net/xenophon/mem3-9.html","notesMarkdown":"The argument about knowledge, conduct, freedom, and appetite follows these two passages. Their combination, setting, and the -μι examples are newly composed; Xenophon does not stage this as one continuous conversation."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-35' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 35 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
