DO $audit36$
DECLARE
  old_reading jsonb := $old${"title":"Ἀπὸ τοῦ ἑαυτοῦ πρὸς τὴν πόλιν","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hellenica 2.4.38–43. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The settlement, return, sacrifice, and oath follow Hellenica 2.4.38–42. The δείκνυμι/ἵημι examples and interpretive questions are course composition. Section 43 describes a later killing of leaders at Eleusis and subsequent reconciliation; it is not the same event as the first return in 403 BCE.","Read supplementary participles as completing verbs of perception or continuance; bring together the module’s patterns without introducing advanced indirect discourse."],"paragraphs":[{"greek":"Οἱ ἐκ τοῦ Πειραιῶς καὶ οἱ ἐκ τοῦ ἄστεως ἐπολέμουν. Παυσανίας δὲ καὶ οἱ πρέσβεις περὶ διαλλαγῶν ἐπράττοντο. τέλος οἱ ἄνδρες ἐπαύσαντο μαχόμενοι.","gloss":[{"greek":"Οἱ ἐκ τοῦ Πειραιῶς","english":"the men from Piraeus"},{"greek":"τοῦ ἄστεως","english":"the city"},{"greek":"οἱ πρέσβεις","english":"the envoys"},{"greek":"διαλλαγῶν","english":"reconciliation"},{"greek":"ἐπαύσαντο μαχόμενοι","english":"stopped fighting; supplementary participle"}]},{"greek":"Οἱ δὲ ἐκ τοῦ Πειραιῶς εἰς τὴν πόλιν ἀνέβησαν. τὰ ὅπλα εἶχον καὶ εἰς τὴν ἀκρόπολιν ἦλθον. ἐκεῖ τῇ Ἀθηνᾷ ἔθυσαν. εἶτα οἱ πολῖται ἐβουλεύοντο.","gloss":[{"greek":"ἀνέβησαν","english":"went up; athematic second aorist"},{"greek":"τὰ ὅπλα","english":"arms"},{"greek":"τὴν ἀκρόπολιν","english":"the Acropolis"},{"greek":"ἔθυσαν","english":"sacrificed"},{"greek":"ἐβουλεύοντο","english":"deliberated"}]},{"greek":"Οἱ πολῖται ὤμοσαν μὴ μνησικακήσειν. οὐκ ἀεὶ τὰ παλαιὰ κακὰ πρὸς τοὺς ἄλλους φέρειν ἔμελλον. χαλεπὸν δὲ τὸ ἔργον· οἱ γὰρ ἄνθρωποι πολλὰ ἔπαθον.","gloss":[{"greek":"ὤμοσαν","english":"swore; aorist of ὄμνυμι"},{"greek":"μὴ μνησικακήσειν","english":"not to bear grudges; future infinitive in the oath"},{"greek":"τὰ παλαιὰ κακὰ","english":"old wrongs"},{"greek":"ἔμελλον","english":"were going to"},{"greek":"ἔπαθον","english":"suffered"}]},{"greek":"Ἐν τῷ διδακτικῷ παραδείγματι ὁ πολίτης τὴν ἀκρόπολιν δείκνυσιν. ὁ φίλος ὁρᾷ τοὺς ἄνδρας ἀναβαίνοντας. «οὗτοι ἤδη παύονται μαχόμενοι· τί δὲ ποιήσουσιν αὔριον;»","gloss":[{"greek":"διδακτικῷ παραδείγματι","english":"teaching example"},{"greek":"δείκνυσιν","english":"points out; present of δείκνυμι"},{"greek":"ὁρᾷ","english":"sees"},{"greek":"ἀναβαίνοντας","english":"going up; supplementary participle with τοὺς ἄνδρας"},{"greek":"αὔριον","english":"tomorrow"}]},{"greek":"Ἄλλο παράδειγμα· ὁ ἀνὴρ ἵησι τὸ βέλος, ὁ δὲ φίλος ἀφίησι τὸν λίθον. τὸ δὲ μὴ βάλλειν καὶ μὴ βλάπτειν κρίσιν ἔχει. οὐ πᾶσα δύναμις εὐθὺς εἰς ἔργον ἔρχεται.","gloss":[{"greek":"ἵησι","english":"sends; present of ἵημι"},{"greek":"τὸ βέλος","english":"missile"},{"greek":"ἀφίησι","english":"lets go of; present of ἀφίημι"},{"greek":"μὴ βάλλειν","english":"not throwing; articular infinitive"},{"greek":"κρίσιν","english":"a decision"}]},{"greek":"Ὁ Ξενοφῶν ὕστερον καὶ περὶ τῶν ἐν Ἐλευσῖνι γράφει· οἱ στρατηγοὶ αὐτῶν ἀπέθανον. οὐ ῥᾳδία ἦν ἡ διαλλαγή. τίς οὖν ἡ σωφροσύνη τοῦ πολίτου; τὴν ἀρχὴν καὶ τὴν ὀργὴν μετὰ κρίσεως ἔχειν.","gloss":[{"greek":"ὕστερον","english":"later"},{"greek":"ἐν Ἐλευσῖνι","english":"at Eleusis"},{"greek":"οἱ στρατηγοὶ","english":"the generals"},{"greek":"ἀπέθανον","english":"died; they were killed in the source"},{"greek":"ἡ διαλλαγή","english":"reconciliation"},{"greek":"μετὰ κρίσεως","english":"with judgment"}]}],"translation":"The men from Piraeus and the men from the city had been fighting. Pausanias and the envoys negotiated reconciliation. At last the men stopped fighting.\n\nThe men from Piraeus went up into the city. They had their arms and came to the Acropolis. There they sacrificed to Athena. Then the citizens deliberated.\n\nThe citizens swore not to bear grudges. They were not going to keep bringing old wrongs against one another. But the task was difficult, for the people had suffered much.\n\nIn the teaching example the citizen points out the Acropolis. His friend sees the men going up. “These men are now ceasing to fight; but what will they do tomorrow?”\n\nAnother example: the man sends a missile, and his companion lets go of a stone. But refraining from throwing and harming involves a decision. Not every power immediately passes into action.\n\nXenophon later also writes about those at Eleusis: their generals died. Reconciliation was not easy. What, then, is the citizen’s self-control? To hold power and anger with judgment.\n","sourceCitation":"Xenophon, Hellenica 2.4.38–43. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1174/1174-h/1174-h.htm https://en.wikipedia.org/wiki/Hellenica https://en.wikisource.org/wiki/Hellenica_(Dakyns)/Book_2/Chapter_4","notesMarkdown":"The settlement, return, sacrifice, and oath follow Hellenica 2.4.38–42. The δείκνυμι/ἵημι examples and interpretive questions are course composition. Section 43 describes a later killing of leaders at Eleusis and subsequent reconciliation; it is not the same event as the first return in 403 BCE."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ἀπὸ τοῦ ἑαυτοῦ πρὸς τὴν πόλιν","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hellenica 2.4.38–43. Read this controlled course adaptation with the glosses, then revisit its source and historical setting on page three.","The settlement, return, sacrifice, and oath follow Hellenica 2.4.38–42. The δείκνυμι/ἵημι examples and interpretive questions are course composition. Section 43 describes a later killing of leaders at Eleusis and subsequent reconciliation; it is not the same event as the first return in 403 BCE.","Read supplementary participles as completing verbs of perception or continuance; bring together the module’s patterns without introducing advanced indirect discourse."],"paragraphs":[{"greek":"Οἱ ἐκ τοῦ Πειραιῶς καὶ οἱ ἐκ τοῦ ἄστεως ἐπολέμουν. Παυσανίας δὲ καὶ οἱ πρέσβεις περὶ διαλλαγῶν ἐπράττοντο. τέλος οἱ ἄνδρες ἐπαύσαντο μαχόμενοι.","gloss":[{"greek":"Οἱ ἐκ τοῦ Πειραιῶς","english":"the men from Piraeus"},{"greek":"τοῦ ἄστεως","english":"the city"},{"greek":"οἱ πρέσβεις","english":"the envoys"},{"greek":"διαλλαγῶν","english":"reconciliation"},{"greek":"ἐπαύσαντο μαχόμενοι","english":"stopped fighting; supplementary participle"}]},{"greek":"Οἱ δὲ ἐκ τοῦ Πειραιῶς εἰς τὴν πόλιν ἀνέβησαν. τὰ ὅπλα εἶχον καὶ εἰς τὴν ἀκρόπολιν ἦλθον. ἐκεῖ τῇ Ἀθηνᾷ ἔθυσαν. εἶτα οἱ πολῖται ἐβουλεύοντο.","gloss":[{"greek":"ἀνέβησαν","english":"went up; athematic second aorist"},{"greek":"τὰ ὅπλα","english":"arms"},{"greek":"τὴν ἀκρόπολιν","english":"the Acropolis"},{"greek":"ἔθυσαν","english":"sacrificed"},{"greek":"ἐβουλεύοντο","english":"deliberated"}]},{"greek":"Οἱ πολῖται ὤμοσαν μὴ μνησικακήσειν. οὐκ ἀεὶ τὰ παλαιὰ κακὰ πρὸς τοὺς ἄλλους φέρειν ἔμελλον. χαλεπὸν δὲ τὸ ἔργον· οἱ γὰρ ἄνθρωποι πολλὰ ἔπαθον.","gloss":[{"greek":"ὤμοσαν","english":"swore; aorist of ὄμνυμι"},{"greek":"μὴ μνησικακήσειν","english":"not to bear grudges; future infinitive in the oath"},{"greek":"τὰ παλαιὰ κακὰ","english":"old wrongs"},{"greek":"ἔμελλον","english":"were going to"},{"greek":"ἔπαθον","english":"suffered"},{"greek":"ὤμοσαν μὴ μνησικακήσειν","english":"they swore not to hold past wrongs against one another; future infinitive after swearing; compare Lesson 40"}]},{"greek":"Ἐν τῷ διδακτικῷ παραδείγματι ὁ πολίτης τὴν ἀκρόπολιν δείκνυσιν. ὁ φίλος ὁρᾷ τοὺς ἄνδρας ἀναβαίνοντας. «οὗτοι ἤδη παύονται μαχόμενοι· τί δὲ ποιήσουσιν αὔριον;»","gloss":[{"greek":"διδακτικῷ παραδείγματι","english":"teaching example"},{"greek":"δείκνυσιν","english":"points out; present of δείκνυμι"},{"greek":"ὁρᾷ","english":"sees"},{"greek":"ἀναβαίνοντας","english":"going up; supplementary participle with τοὺς ἄνδρας"},{"greek":"αὔριον","english":"tomorrow"}]},{"greek":"Ἐν ἀσκήσει περὶ τοῦ τὰ ὅπλα θεῖναι συγκρίνομεν· ὁ μὲν ἀνὴρ ἵησι τὸ βέλος, ὁ δὲ φίλος ἀφίησι τὸν λίθον καὶ παύεται μαχόμενος. τίς ἀφίησι πρᾶγμα, τίς δὲ παύεται πράττων; τὸ δὲ μὴ βάλλειν καὶ μὴ βλάπτειν κρίσιν ἔχει. οὐ πᾶσα δύναμις εὐθὺς εἰς ἔργον ἔρχεται.","gloss":[{"greek":"θεῖναι","english":"to lay down; aorist infinitive of τίθημι"},{"greek":"ἵησι","english":"sends; present of ἵημι"},{"greek":"ἀφίησι","english":"lets go of; present of ἀφίημι with an object"},{"greek":"παύεται μαχόμενος","english":"ceases fighting; παύομαι with supplementary participle"},{"greek":"πράττων","english":"doing; present participle"},{"greek":"βέλος","english":"missile"},{"greek":"κρίσιν","english":"a decision"},{"greek":"μὴ βάλλειν","english":"not throwing; articular infinitive"}]},{"greek":"Ὁ Ξενοφῶν ὕστερον καὶ περὶ τῶν ἐν Ἐλευσῖνι γράφει· οἱ στρατηγοὶ αὐτῶν ἀπέθανον. οὐ ῥᾳδία ἦν ἡ διαλλαγή. τίς οὖν ἡ σωφροσύνη τοῦ πολίτου; τὴν ἀρχὴν καὶ τὴν ὀργὴν μετὰ κρίσεως ἔχειν.","gloss":[{"greek":"ὕστερον","english":"later"},{"greek":"ἐν Ἐλευσῖνι","english":"at Eleusis"},{"greek":"οἱ στρατηγοὶ","english":"the generals"},{"greek":"ἀπέθανον","english":"died; they were killed in the source"},{"greek":"ἡ διαλλαγή","english":"reconciliation"},{"greek":"μετὰ κρίσεως","english":"with judgment"}]}],"translation":"The men from Piraeus and the men from the city had been fighting. Pausanias and the envoys negotiated reconciliation. At last the men stopped fighting.\n\nThe men from Piraeus went up into the city. They had their arms and came to the Acropolis. There they sacrificed to Athena. Then the citizens deliberated.\n\nThe citizens swore not to bear grudges. They were not going to keep bringing old wrongs against one another. But the task was difficult, for the people had suffered much.\n\nIn the teaching example the citizen points out the Acropolis. His friend sees the men going up. “These men are now ceasing to fight; but what will they do tomorrow?”\n\nIn an exercise about laying down arms we compare: one man sends a missile, while his companion lets go of the stone and ceases fighting. Who lets go of an object, and who ceases doing an action? Not throwing and not harming involves a decision. Not every power immediately passes into action.\n\nXenophon later also writes about those at Eleusis: their generals died. Reconciliation was not easy. What, then, is the citizen’s self-control? To hold power and anger with judgment.\n","sourceCitation":"Xenophon, Hellenica 2.4.38–43. Newly composed controlled Greek adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1174/1174-h/1174-h.htm https://en.wikipedia.org/wiki/Hellenica https://en.wikisource.org/wiki/Hellenica_(Dakyns)/Book_2/Chapter_4","notesMarkdown":"The settlement, return, sacrifice, and oath follow Hellenica 2.4.38–42. The δείκνυμι/ἵημι examples and interpretive questions are course composition. Section 43 describes a later killing of leaders at Eleusis and subsequent reconciliation; it is not the same event as the first return in 403 BCE."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-36' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 36 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit36$;
DO $audit37$
DECLARE
  old_reading jsonb := $old${"title":"Τί δίκαιόν ἐστιν;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Cyropaedia 1.3.16–18. 253 Greek words in 5 paragraphs.","The coat dispute and Cyrus’s conversation with Mandane follow Cyropaedia 1.3.16–18. The deliberative questions and closing reflection are composed for this course; neither these speeches nor the scene is an independent record of Persian schooling.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Κῦρος ἔτι παῖς ὢν παρὰ τῷ πάππῳ διέτριβεν. ἡ δὲ μήτηρ Μανδάνη περὶ τῆς παιδείας αὐτοῦ ἠρώτα. οὐ μόνον γὰρ τὸ σῶμα ἀσκεῖν ἔδει τὸν παῖδα, ἀλλὰ καὶ τὰ δίκαια μανθάνειν. ὁ δὲ Κῦρος ἔλεγεν ὅτι παρὰ τοῖς Πέρσαις ἐμάνθανε κρίνειν καὶ ὅτι ὁ διδάσκαλος πολλάκις αὐτὸν δικαστὴν ἐποίει.","gloss":[{"greek":"πάππῳ","english":"grandfather"},{"greek":"διέτριβεν","english":"was staying"},{"greek":"ἀσκεῖν","english":"to train"},{"greek":"ἐμάνθανε","english":"was learning"},{"greek":"δικαστὴν","english":"a judge"}]},{"greek":"Δύο γὰρ παῖδες περὶ χιτώνων διεφέροντο. ὁ μὲν μέγας παῖς μικρὸν χιτῶνα εἶχεν, ὁ δὲ μικρὸς μέγαν. ὁ οὖν μέγας τὸν τοῦ μικροῦ χιτῶνα ἀφελόμενος τὸν ἑαυτοῦ ἐκείνῳ ἔδωκεν. ἑκάτερος οὕτω χιτῶνα τῷ σώματι ἁρμόττοντα εἶχεν· ἀλλὰ ὁ μικρὸς οὐκ ἐβούλετο τὸν ἑαυτοῦ ἀπολέσαι. οὐ γὰρ ἑκὼν τὴν ἀλλαγὴν ἐποιήσατο.","gloss":[{"greek":"χιτώνων","english":"tunics"},{"greek":"διεφέροντο","english":"were disputing"},{"greek":"ἀφελόμενος","english":"having taken away"},{"greek":"ἁρμόττοντα","english":"fitting"},{"greek":"ἑκὼν","english":"willingly"},{"greek":"ἀλλαγὴν","english":"exchange"}]},{"greek":"Ὁ Κῦρος τὸ πρᾶγμα ἐξήταζεν. τί ποιήσω; πότερον τὸ μέγεθος τῶν χιτώνων σκοπῶ ἢ τοὺς κυρίους; ὁ μὲν γὰρ χιτὼν τῷ μεγάλῳ παιδὶ καλῶς ἁρμόττει, ὁ δὲ τῷ μικρῷ. κρίνωμεν οὖν κατὰ τὸ χρήσιμον, ἵνα ἑκάτερος τὸ ἁρμόττον ἔχῃ. ταύτην τὴν κρίσιν ἐποιήσατο, νομίζων ἀμφοτέρους ὠφελεῖν.","gloss":[{"greek":"ποιήσω","english":"should I do? aorist subjunctive in deliberation"},{"greek":"σκοπῶ","english":"should I consider? present subjunctive here"},{"greek":"κυρίους","english":"owners"},{"greek":"κρίνωμεν","english":"let us judge"},{"greek":"ἔχῃ","english":"may have; purpose"},{"greek":"ἀμφοτέρους","english":"both"}]},{"greek":"Ὁ δὲ διδάσκαλος οὐκ ἐπῄνεσε τὴν κρίσιν. ἄλλο γάρ ἐστι τὸ ἁρμόττον, ἄλλο δὲ τὸ δίκαιον. οὐ τοῦτο μόνον ζητῶμεν, τίς χιτὼν καλῶς ἔχει, ἀλλὰ καὶ τίνος ἐστίν. μὴ τὸν κύριον ἀδικήσωμεν, ἵνα τὸν ἕτερον ὠφελήσωμεν. ὁ λαβὼν βίᾳ οὐ διὰ τοῦτο κύριος γίγνεται, ὅτι αὐτῷ τὸ κτῆμα χρήσιμόν ἐστιν.","gloss":[{"greek":"ἐπῄνεσε","english":"praised"},{"greek":"τίνος","english":"whose"},{"greek":"ἀδικήσωμεν","english":"let us wrong; with μή, let us not wrong"},{"greek":"ὠφελήσωμεν","english":"may benefit"},{"greek":"βίᾳ","english":"by force"},{"greek":"κτῆμα","english":"possession"}]},{"greek":"Ἡ Μανδάνη τὸν λόγον ἤκουε καὶ περὶ τῶν νόμων διέλεγετο. ὁ γὰρ ἄρχων οὐ πανταχοῦ τὴν αὐτὴν ἐξουσίαν ἔχει. ὁ παῖς οὖν μὴ μόνον τὰ τῶν ἰσχυρῶν ἔργα θαυμαζέτω, ἀλλὰ τὸ δίκαιον ἐξεταζέτω. ἀκούσωμεν καὶ τοῦ ἀσθενεστέρου, ἵνα μὴ ἡ δύναμις ἀντὶ τοῦ νόμου κρίνῃ. οὕτως ἡ περὶ δύο χιτώνων ζήτησις εἰς τὴν περὶ ἀρχῆς παιδείαν ἄγει.","gloss":[{"greek":"πανταχοῦ","english":"everywhere"},{"greek":"ἐξουσίαν","english":"authority"},{"greek":"θαυμαζέτω","english":"let him admire; imperative"},{"greek":"ἀσθενεστέρου","english":"weaker person"},{"greek":"κρίνῃ","english":"may judge"},{"greek":"ζήτησις","english":"inquiry"}]}],"translation":"While still a boy, Cyrus was staying with his grandfather. His mother Mandane asked about his education. For the boy needed not only to train his body but also to learn what was just. Cyrus said that among the Persians he learned to judge and that the teacher often made him a judge.\n\nTwo boys were disputing about tunics. The large boy had a small tunic, and the small boy a large one. The large boy took the small boy’s tunic and gave him his own. Each thus had a tunic fitting his body; but the small boy did not wish to lose his own. For he had not made the exchange willingly.\n\nCyrus examined the matter. What should I do? Should I consider the size of the tunics or their owners? One tunic fits the large boy well, the other the small boy. Let us therefore judge by usefulness, so that each may have what fits. He made this judgment, thinking that he was benefiting both.\n\nThe teacher did not praise the judgment. What fits is one thing, what is just another. Let us investigate not only which tunic fits well, but also whose it is. Let us not wrong the owner in order to benefit the other person. Someone who takes by force does not thereby become the owner because the possession is useful to him.\n\nMandane listened to the account and discussed laws. For a ruler does not have the same authority everywhere. Let the boy therefore not merely admire the deeds of the powerful, but examine what is just. Let us listen also to the weaker person, so that power may not judge in place of law. Thus the inquiry about two tunics leads into education about rule.\n","sourceCitation":"Xenophon, Cyropaedia 1.3.16–18. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/2085/2085-h/2085-h.htm","notesMarkdown":"The coat dispute and Cyrus’s conversation with Mandane follow Cyropaedia 1.3.16–18. The deliberative questions and closing reflection are composed for this course; neither these speeches nor the scene is an independent record of Persian schooling."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Τί δίκαιόν ἐστιν;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Cyropaedia 1.3.16–18. 265 Greek words in 5 paragraphs.","The coat dispute and Cyrus’s conversation with Mandane follow Cyropaedia 1.3.16–18. The deliberative questions and closing reflection are composed for this course; neither these speeches nor the scene is an independent record of Persian schooling.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Κῦρος ἔτι παῖς ὢν παρὰ τῷ πάππῳ διέτριβεν. ἡ δὲ μήτηρ Μανδάνη περὶ τῆς παιδείας αὐτοῦ ἠρώτα. οὐ μόνον γὰρ τὸ σῶμα ἀσκεῖν ἔδει τὸν παῖδα, ἀλλὰ καὶ τὰ δίκαια μανθάνειν. ὁ δὲ Κῦρος ἔλεγεν ὅτι παρὰ τοῖς Πέρσαις ἐμάνθανε κρίνειν καὶ ὅτι ὁ διδάσκαλος πολλάκις αὐτὸν δικαστὴν ἐποίει.","gloss":[{"greek":"πάππῳ","english":"grandfather"},{"greek":"διέτριβεν","english":"was staying"},{"greek":"ἀσκεῖν","english":"to train"},{"greek":"ἐμάνθανε","english":"was learning"},{"greek":"δικαστὴν","english":"a judge"}]},{"greek":"Δύο γὰρ παῖδες περὶ χιτώνων διεφέροντο. ὁ μὲν μέγας παῖς μικρὸν χιτῶνα εἶχεν, ὁ δὲ μικρὸς μέγαν. ὁ οὖν μέγας τὸν τοῦ μικροῦ χιτῶνα ἀφελόμενος τὸν ἑαυτοῦ ἐκείνῳ ἔδωκεν. ἑκάτερος οὕτω χιτῶνα τῷ σώματι ἁρμόττοντα εἶχεν· ἀλλὰ ὁ μικρὸς οὐκ ἐβούλετο τὸν ἑαυτοῦ ἀπολέσαι. οὐ γὰρ ἑκὼν τὴν ἀλλαγὴν ἐποιήσατο.","gloss":[{"greek":"χιτώνων","english":"tunics"},{"greek":"διεφέροντο","english":"were disputing"},{"greek":"ἀφελόμενος","english":"having taken away"},{"greek":"ἁρμόττοντα","english":"fitting"},{"greek":"ἑκὼν","english":"willingly"},{"greek":"ἀλλαγὴν","english":"exchange"}]},{"greek":"Ὁ Κῦρος τὸ πρᾶγμα ἐξήταζεν. τί ποιήσω; πότερον τὸ μέγεθος τῶν χιτώνων σκοπῶ ἢ τοὺς κυρίους; ὁ μὲν γὰρ χιτὼν τῷ μεγάλῳ παιδὶ καλῶς ἁρμόττει, ὁ δὲ τῷ μικρῷ. κρίνωμεν οὖν κατὰ τὸ χρήσιμον, ἵνα ἑκάτερος τὸ ἁρμόττον ἔχῃ. ταύτην τὴν κρίσιν ἐποιήσατο, νομίζων ἀμφοτέρους ὠφελεῖν.","gloss":[{"greek":"ποιήσω","english":"should I do? aorist subjunctive in deliberation"},{"greek":"σκοπῶ","english":"should I consider? present subjunctive here"},{"greek":"κυρίους","english":"owners"},{"greek":"κρίνωμεν","english":"let us judge"},{"greek":"ἔχῃ","english":"may have; purpose"},{"greek":"ἀμφοτέρους","english":"both"}]},{"greek":"Ὁ δὲ διδάσκαλος οὐκ ἐπῄνεσε τὴν κρίσιν. ἄλλο γάρ ἐστι τὸ ἁρμόττον, ἄλλο δὲ τὸ δίκαιον. οὐ τοῦτο μόνον ζητῶμεν, τίς χιτὼν καλῶς ἔχει, ἀλλὰ καὶ τίνος ἐστίν. μὴ τὸν κύριον ἀδικήσωμεν, ἵνα τὸν ἕτερον ὠφελήσωμεν. ὁ λαβὼν βίᾳ οὐ διὰ τοῦτο κύριος γίγνεται, ὅτι αὐτῷ τὸ κτῆμα χρήσιμόν ἐστιν. Ἐν τῇ ἀσκήσει λέγωμεν· ἐξετάζωμεν τὴν ἀλλαγήν, ἵνα μηδέτερος τῶν παίδων ἀδικηθῇ.","gloss":[{"greek":"ἐπῄνεσε","english":"praised"},{"greek":"τίνος","english":"whose"},{"greek":"ἀδικήσωμεν","english":"let us wrong; with μή, let us not wrong"},{"greek":"ὠφελήσωμεν","english":"may benefit"},{"greek":"βίᾳ","english":"by force"},{"greek":"κτῆμα","english":"possession"},{"greek":"ἐξετάζωμεν","english":"let us examine; present active subjunctive"},{"greek":"μηδέτερος","english":"neither of the two"},{"greek":"ἀδικηθῇ","english":"may be wronged; aorist passive subjunctive of ἀδικέω in a purpose clause"}]},{"greek":"Ἡ Μανδάνη τὸν λόγον ἤκουε καὶ περὶ τῶν νόμων διέλεγετο. ὁ γὰρ ἄρχων οὐ πανταχοῦ τὴν αὐτὴν ἐξουσίαν ἔχει. ὁ παῖς οὖν μὴ μόνον τὰ τῶν ἰσχυρῶν ἔργα θαυμαζέτω, ἀλλὰ τὸ δίκαιον ἐξεταζέτω. ἀκούσωμεν καὶ τοῦ ἀσθενεστέρου, ἵνα μὴ ἡ δύναμις ἀντὶ τοῦ νόμου κρίνῃ. οὕτως ἡ περὶ δύο χιτώνων ζήτησις εἰς τὴν περὶ ἀρχῆς παιδείαν ἄγει.","gloss":[{"greek":"πανταχοῦ","english":"everywhere"},{"greek":"ἐξουσίαν","english":"authority"},{"greek":"θαυμαζέτω","english":"let him admire; imperative"},{"greek":"ἀσθενεστέρου","english":"weaker person"},{"greek":"κρίνῃ","english":"may judge"},{"greek":"ζήτησις","english":"inquiry"}]}],"translation":"While still a boy, Cyrus was staying with his grandfather. His mother Mandane asked about his education. For the boy needed not only to train his body but also to learn what was just. Cyrus said that among the Persians he learned to judge and that the teacher often made him a judge.\n\nTwo boys were disputing about tunics. The large boy had a small tunic, and the small boy a large one. The large boy took the small boy’s tunic and gave him his own. Each thus had a tunic fitting his body; but the small boy did not wish to lose his own. For he had not made the exchange willingly.\n\nCyrus examined the matter. What should I do? Should I consider the size of the tunics or their owners? One tunic fits the large boy well, the other the small boy. Let us therefore judge by usefulness, so that each may have what fits. He made this judgment, thinking that he was benefiting both.\n\nThe teacher did not praise the judgment. What fits is one thing, what is just another. Let us investigate not only which tunic fits well, but also whose it is. Let us not wrong the owner in order to benefit the other person. Someone who takes by force does not thereby become the owner because the possession is useful to him. In the exercise let us say: let us examine the exchange so that neither boy is wronged.\n\nMandane listened to the account and discussed laws. For a ruler does not have the same authority everywhere. Let the boy therefore not merely admire the deeds of the powerful, but examine what is just. Let us listen also to the weaker person, so that power may not judge in place of law. Thus the inquiry about two tunics leads into education about rule.\n","sourceCitation":"Xenophon, Cyropaedia 1.3.16–18. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/2085/2085-h/2085-h.htm","notesMarkdown":"The coat dispute and Cyrus’s conversation with Mandane follow Cyropaedia 1.3.16–18. The deliberative questions and closing reflection are composed for this course; neither these speeches nor the scene is an independent record of Persian schooling."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-37' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 37 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit37$;
DO $audit38$
DECLARE
  old_reading jsonb := $old${"title":"Τίς φυλάττει τὰ ἐν τῇ οἰκίᾳ;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Oeconomicus 9.11–15; brief comparison with 14.3–10. 253 Greek words in 5 paragraphs.","The choice, training, and incentives of a housekeeper follow Oeconomicus 9.11–15, with comparison to 14.3–10. Proposals and questions are course compositions. The enslaved housekeeper’s private thoughts are not supplied by Xenophon and are not invented here.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Ἰσχόμαχος τῷ Σωκράτει περὶ τῆς οἰκίας λέγει. οὐ γὰρ ἀρκεῖ πολλὰ κτήματα κεκτῆσθαι· δεῖ καὶ εἰδέναι ποῦ ἕκαστον κεῖται καὶ τίς αὐτὸ φυλάττει. ἡ γυνὴ καὶ ὁ ἀνὴρ περὶ τῆς ταμίας βουλεύονται. ζητοῦσι γυναῖκα ἥτις τῶν ἐν τῇ οἰκίᾳ ἐπιμελήσεται καὶ τὰ διδόμενα μνημονεύσει.","gloss":[{"greek":"ἀρκεῖ","english":"it is enough"},{"greek":"κεκτῆσθαι","english":"to possess; supported perfect infinitive"},{"greek":"εἰδέναι","english":"to know; supported form"},{"greek":"ταμίας","english":"housekeeper"},{"greek":"ἐπιμελήσεται","english":"will care for"},{"greek":"μνημονεύσει","english":"will remember"}]},{"greek":"Ὁ Ἰσχόμαχος τὴν ἐπιμέλειαν καὶ τὴν μνήμην ἐπαινεῖ. τὴν ταμίαν δεῖ τὰ μὲν δέχεσθαι, τὰ δὲ διδόναι, τὰ δὲ φυλάττειν. οὐ πάντας τοὺς ἀνθρώπους ἴσους νομίζει πρὸς ταῦτα. ἀλλὰ ζητεῖ τίς τῶν ἡδονῶν κρατεῖ καὶ τίς ἐθέλει πιστὴ εἶναι. τοιαύτην γυναῖκα αἱροῦνται, ἵνα τὰ χρήματα μὴ ἀπόληται.","gloss":[{"greek":"ἐπιμέλειαν","english":"care"},{"greek":"μνήμην","english":"memory"},{"greek":"δέχεσθαι","english":"to receive"},{"greek":"διδόναι","english":"to give"},{"greek":"αἱροῦνται","english":"they choose"},{"greek":"ἀπόληται","english":"may perish; aorist middle subjunctive"}]},{"greek":"Πῶς οὖν παιδεύωμεν τὴν ταμίαν; τί αὐτῇ δῶμεν, καὶ ποῦ τὰ σκεύη θῶμεν; τοιάσδε ἐρωτήσεις ἐν τῷ μαθήματι ποιοῦμεν. ὁ Ἰσχόμαχος διδάσκει τὴν γυναῖκα τὰ χρήματα κατὰ χώραν τιθέναι. ἕκαστον γὰρ τόπον ἔχει, ἵνα ῥᾳδίως εὑρίσκωμεν ὃ ζητοῦμεν. μὴ τὰ χρήσιμα ἐν ἀταξίᾳ κρύπτωμεν.","gloss":[{"greek":"δῶμεν","english":"should we give? aorist subjunctive"},{"greek":"θῶμεν","english":"should we place? aorist subjunctive"},{"greek":"σκεύη","english":"equipment"},{"greek":"τοιάσδε","english":"of this kind"},{"greek":"κατὰ χώραν","english":"in the proper place"},{"greek":"ἀταξίᾳ","english":"disorder"}]},{"greek":"Οὐ μόνον δὲ τόπους ἀλλὰ καὶ τρόπους διδάσκουσιν. ὁ κύριος τὴν πιστὴν τιμᾷ καὶ τῇ ἐπιμελεῖ δῶρα δίδωσιν. ἵνα πιστὴ ᾖ, πειρῶνται καὶ εὐνοϊκὴν αὐτὴν ποιεῖν. ἐν δὲ τῇ τοῦ Ἰσχομάχου διηγήσει αἱ τιμαὶ καὶ αἱ ζημίαι πρὸς τὸ τῶν κυρίων συμφέρον βλέπουσιν. οἱ γὰρ κύριοι τὸν κανόνα τίθενται.","gloss":[{"greek":"ᾖ","english":"may be; subjunctive of εἰμί"},{"greek":"εὐνοϊκὴν","english":"well disposed"},{"greek":"διηγήσει","english":"account"},{"greek":"ζημίαι","english":"penalties"},{"greek":"συμφέρον","english":"advantage"},{"greek":"κανόνα","english":"standard"}]},{"greek":"Ἡ δὲ ταμία δούλη ἐστίν. ἡ ἐπιμέλεια τῶν χρημάτων οὐκ ἐλευθέραν αὐτὴν ποιεῖ. πολλὴν μὲν ἔχει χρείαν ὁ οἶκος τῆς ἐργασίας αὐτῆς, ἡ δὲ οὐ τὴν αὐτὴν ἐξουσίαν ἔχει τοῖς κυρίοις. μὴ οὖν τὴν τάξιν μόνον θαυμάσωμεν· ἐξετάσωμεν καὶ τίς κελεύει καὶ τίς πείθεται. οὐ γὰρ ἡ αὐτὴ ἐλευθερία πᾶσι τοῖς ἐν τῇ οἰκίᾳ ἐστίν. τίνα νόμον θῶμεν, ἵνα μὴ μόνον τὰ κτήματα ἀλλὰ καὶ τοὺς ἐργαζομένους φυλάττωμεν;","gloss":[{"greek":"δούλη","english":"enslaved woman"},{"greek":"ἐλευθέραν","english":"free"},{"greek":"ἐργασίας","english":"work"},{"greek":"πείθεται","english":"obeys"},{"greek":"θῶμεν","english":"should we establish?"},{"greek":"ἐργαζομένους","english":"people working"}]}],"translation":"Ischomachus speaks to Socrates about the household. For it is not enough to possess many things; one must also know where each lies and who guards it. Wife and husband deliberate about the housekeeper. They seek a woman who will care for the household’s contents and remember what is given.\n\nIschomachus praises care and memory. The housekeeper must receive some things, give others out, and guard others. He does not consider all people equally suited to these tasks. Rather, he asks who controls her pleasures and who is willing to be trustworthy. They choose such a woman so that the property may not be lost.\n\nHow then should we educate the housekeeper? What should we give her, and where should we place the equipment? We pose questions of this kind in the lesson. Ischomachus teaches his wife to place possessions in their proper locations. Each thing has a place, so that we may easily find what we seek. Let us not hide useful things in disorder.\n\nThey teach not only locations but also habits. The owner honors the trustworthy woman and gives gifts to the careful one. So that she may be trustworthy, they also try to make her well disposed. In Ischomachus’s account, however, honors and penalties look toward the owners’ advantage. For the owners set the standard.\n\nThe housekeeper is enslaved. Care of the property does not make her free. The household has great need of her work, but she does not have the same authority as the owners. Let us therefore not admire order alone; let us also examine who commands and who obeys. For not everyone in the household has the same freedom. What rule should we establish so that we may protect not only possessions but also the people who work?\n","sourceCitation":"Xenophon, Oeconomicus 9.11–15; brief comparison with 14.3–10. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1173/1173-h/1173-h.htm","notesMarkdown":"The choice, training, and incentives of a housekeeper follow Oeconomicus 9.11–15, with comparison to 14.3–10. Proposals and questions are course compositions. The enslaved housekeeper’s private thoughts are not supplied by Xenophon and are not invented here."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Τίς φυλάττει τὰ ἐν τῇ οἰκίᾳ;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Oeconomicus 9.11–15; brief comparison with 14.3–10. 279 Greek words in 5 paragraphs.","The choice, training, and incentives of a housekeeper follow Oeconomicus 9.11–15, with comparison to 14.3–10. Proposals and questions are course compositions. The enslaved housekeeper’s private thoughts are not supplied by Xenophon and are not invented here.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Ἰσχόμαχος τῷ Σωκράτει περὶ τῆς οἰκίας λέγει. οὐ γὰρ ἀρκεῖ πολλὰ κτήματα κεκτῆσθαι· δεῖ καὶ εἰδέναι ποῦ ἕκαστον κεῖται καὶ τίς αὐτὸ φυλάττει. ἡ γυνὴ καὶ ὁ ἀνὴρ περὶ τῆς ταμίας βουλεύονται. ζητοῦσι γυναῖκα ἥτις τῶν ἐν τῇ οἰκίᾳ ἐπιμελήσεται καὶ τὰ διδόμενα μνημονεύσει.","gloss":[{"greek":"ἀρκεῖ","english":"it is enough"},{"greek":"κεκτῆσθαι","english":"to possess; perfect middle infinitive of κτάομαι with present sense; supported reading vocabulary"},{"greek":"εἰδέναι","english":"to know; perfect infinitive of οἶδα with present meaning; supported reading vocabulary"},{"greek":"ταμίας","english":"housekeeper"},{"greek":"ἐπιμελήσεται","english":"will care for"},{"greek":"μνημονεύσει","english":"will remember"}]},{"greek":"Ὁ Ἰσχόμαχος τὴν ἐπιμέλειαν καὶ τὴν μνήμην ἐπαινεῖ. τὴν ταμίαν δεῖ τὰ μὲν δέχεσθαι, τὰ δὲ διδόναι, τὰ δὲ φυλάττειν. οὐ πάντας τοὺς ἀνθρώπους ἴσους νομίζει πρὸς ταῦτα. ἀλλὰ ζητεῖ τίς τῶν ἡδονῶν κρατεῖ καὶ τίς ἐθέλει πιστὴ εἶναι. τοιαύτην γυναῖκα αἱροῦνται, ἵνα τὰ χρήματα μὴ ἀπόληται.","gloss":[{"greek":"ἐπιμέλειαν","english":"care"},{"greek":"μνήμην","english":"memory"},{"greek":"δέχεσθαι","english":"to receive"},{"greek":"διδόναι","english":"to give"},{"greek":"αἱροῦνται","english":"they choose"},{"greek":"ἀπόληται","english":"may perish; aorist middle subjunctive"}]},{"greek":"Πῶς οὖν παιδεύωμεν τὴν ταμίαν; τί αὐτῇ δῶμεν, καὶ ποῦ τὰ σκεύη θῶμεν; τοιάσδε ἐρωτήσεις ἐν τῷ μαθήματι ποιοῦμεν. ὁ Ἰσχόμαχος διδάσκει τὴν γυναῖκα τὰ χρήματα κατὰ χώραν τιθέναι. ἕκαστον γὰρ τόπον ἔχει, ἵνα ῥᾳδίως εὑρίσκωμεν ὃ ζητοῦμεν. μὴ τὰ χρήσιμα ἐν ἀταξίᾳ κρύπτωμεν.","gloss":[{"greek":"δῶμεν","english":"should we give? aorist subjunctive"},{"greek":"θῶμεν","english":"should we place? aorist subjunctive"},{"greek":"σκεύη","english":"equipment"},{"greek":"τοιάσδε","english":"of this kind"},{"greek":"κατὰ χώραν","english":"in the proper place"},{"greek":"ἀταξίᾳ","english":"disorder"}]},{"greek":"Οὐ μόνον δὲ τόπους ἀλλὰ καὶ τρόπους διδάσκουσιν. ὁ κύριος τὴν πιστὴν τιμᾷ καὶ τῇ ἐπιμελεῖ δῶρα δίδωσιν. ἵνα πιστὴ ᾖ, πειρῶνται καὶ εὐνοϊκὴν αὐτὴν ποιεῖν. ἐν δὲ τῇ τοῦ Ἰσχομάχου διηγήσει αἱ τιμαὶ καὶ αἱ ζημίαι πρὸς τὸ τῶν κυρίων συμφέρον βλέπουσιν. οἱ γὰρ κύριοι τὸν κανόνα τίθενται.","gloss":[{"greek":"ᾖ","english":"may be; subjunctive of εἰμί"},{"greek":"εὐνοϊκὴν","english":"well disposed"},{"greek":"διηγήσει","english":"account"},{"greek":"ζημίαι","english":"penalties"},{"greek":"συμφέρον","english":"advantage"},{"greek":"κανόνα","english":"standard"}]},{"greek":"Ἡ δὲ ταμία δούλη ἐστίν. ἡ ἐπιμέλεια τῶν χρημάτων οὐκ ἐλευθέραν αὐτὴν ποιεῖ. πολλὴν μὲν ἔχει χρείαν ὁ οἶκος τῆς ἐργασίας αὐτῆς, ἡ δὲ οὐ τὴν αὐτὴν ἐξουσίαν ἔχει τοῖς κυρίοις. μὴ οὖν τὴν τάξιν μόνον θαυμάσωμεν· ἐξετάσωμεν καὶ τίς κελεύει καὶ τίς πείθεται. οὐ γὰρ ἡ αὐτὴ ἐλευθερία πᾶσι τοῖς ἐν τῇ οἰκίᾳ ἐστίν. τίνα νόμον θῶμεν, ἵνα μὴ μόνον τὰ κτήματα ἀλλὰ καὶ τοὺς ἐργαζομένους φυλάττωμεν; Ἐν διδακτικῷ διαλόγῳ οἱ κύριοι λέγουσι· «τίνα κανόνα θώμεθα; ἀφῶμεν τὴν ταμίαν τοῦ ἔργου, ἵνα ἀναπαύηται.» οὗτος ὁ λόγος ἄσκησίς ἐστιν, οὐ μαρτυρία περὶ νέας ἐλευθερίας.","gloss":[{"greek":"δούλη","english":"enslaved woman"},{"greek":"ἐλευθέραν","english":"free"},{"greek":"ἐργασίας","english":"work"},{"greek":"πείθεται","english":"obeys"},{"greek":"θῶμεν","english":"should we establish?"},{"greek":"ἐργαζομένους","english":"people working"},{"greek":"θώμεθα","english":"shall we establish for ourselves? aorist middle subjunctive of τίθημι"},{"greek":"ἀφῶμεν","english":"let us release; aorist active subjunctive of ἀφίημι"},{"greek":"τοῦ ἔργου","english":"from the task; genitive of separation"},{"greek":"ἀναπαύηται","english":"may rest; present middle subjunctive"}]}],"translation":"Ischomachus speaks to Socrates about the household. For it is not enough to possess many things; one must also know where each lies and who guards it. Wife and husband deliberate about the housekeeper. They seek a woman who will care for the household’s contents and remember what is given.\n\nIschomachus praises care and memory. The housekeeper must receive some things, give others out, and guard others. He does not consider all people equally suited to these tasks. Rather, he asks who controls her pleasures and who is willing to be trustworthy. They choose such a woman so that the property may not be lost.\n\nHow then should we educate the housekeeper? What should we give her, and where should we place the equipment? We pose questions of this kind in the lesson. Ischomachus teaches his wife to place possessions in their proper locations. Each thing has a place, so that we may easily find what we seek. Let us not hide useful things in disorder.\n\nThey teach not only locations but also habits. The owner honors the trustworthy woman and gives gifts to the careful one. So that she may be trustworthy, they also try to make her well disposed. In Ischomachus’s account, however, honors and penalties look toward the owners’ advantage. For the owners set the standard.\n\nThe housekeeper is enslaved. Care of the property does not make her free. The household has great need of her work, but she does not have the same authority as the owners. Let us therefore not admire order alone; let us also examine who commands and who obeys. For not everyone in the household has the same freedom. What rule should we establish so that we may protect not only possessions but also the people who work? In a teaching dialogue the owners say: “What rule shall we establish for ourselves? Let us release the housekeeper from the task so that she may rest.” This speech is an exercise, not testimony to a new freedom.\n","sourceCitation":"Xenophon, Oeconomicus 9.11–15; brief comparison with 14.3–10. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1173/1173-h/1173-h.htm","notesMarkdown":"The choice, training, and incentives of a housekeeper follow Oeconomicus 9.11–15, with comparison to 14.3–10. Proposals and questions are course compositions. The enslaved housekeeper’s private thoughts are not supplied by Xenophon and are not invented here."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-38' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 38 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit38$;
DO $audit39$
DECLARE
  old_reading jsonb := $old${"title":"Ὁ στρατηγὸς λόγον δίδωσιν","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Anabasis 5.8.1–12 and selected 5.8.13–26. 254 Greek words in 5 paragraphs.","Based on Anabasis 5.8.1–26. Xenophon narrates accusations against himself and his own defense. The condensed dialogue and general clauses are teaching adaptations; his explanation is presented as his claim, not an independently established verdict.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Οἱ στρατιῶται, ἐκ πολλῶν κινδύνων σωθέντες, οὐ πάντων τῶν κακῶν ἐπαύσαντο. ἔτι γὰρ περὶ μισθοῦ καὶ τροφῆς καὶ τῶν στρατηγῶν ἔργων διεφέροντο. ἐν τῇ ἐκκλησίᾳ τινὲς τὸν Ξενοφῶντα ᾐτιῶντο ὅτι ἄνδρας ἔπαισεν. ὁ δὲ οὐκ ἀπῆλθεν, ἀλλὰ λόγον δοῦναι ἤθελεν. ἐρωτᾷ οὖν τίς ἐστιν ὁ κατηγορῶν καὶ πότε ἔπαθεν ἃ λέγει.","gloss":[{"greek":"σωθέντες","english":"having been saved"},{"greek":"μισθοῦ","english":"pay"},{"greek":"ᾐτιῶντο","english":"were accusing"},{"greek":"ἔπαισεν","english":"struck"},{"greek":"λόγον δοῦναι","english":"to give an account"},{"greek":"κατηγορῶν","english":"accusing"}]},{"greek":"Εἷς τῶν ἀνδρῶν ἀναστὰς λέγει ὅτι ὑπὸ τοῦ στρατηγοῦ ἐπλήγη. ὁ Ξενοφῶν ἐρωτᾷ διὰ τί. οὐ γὰρ ἀρκεῖ, φησίν, εἰπεῖν ὅτι ἔπαθές τι· δεῖ καὶ τὰ πρὸ τοῦ ἔργου δηλοῦν. οἱ δὲ παρόντες ἀκούουσιν ἀμφοτέρων. ἡ μὲν αἰτία χαλεπή ἐστιν, ἡ δὲ ἀπόκρισις οὐ πᾶσαν ἀπορίαν εὐθὺς λύει. δεῖ οὖν ἀκριβῶς ἐξετάζειν τὰ λεγόμενα.","gloss":[{"greek":"ἀναστὰς","english":"having stood up"},{"greek":"ἐπλήγη","english":"was struck"},{"greek":"ἀρκεῖ","english":"it is enough"},{"greek":"ἔπαθές","english":"you suffered"},{"greek":"δηλοῦν","english":"to make clear"},{"greek":"ἀπόκρισις","english":"response"}]},{"greek":"Ὁ Ξενοφῶν τὴν πορείαν ἀναμιμνῄσκει τοὺς στρατιώτας. ἐν γὰρ τῷ χειμῶνι πολλοὶ ἔκαμνον, καὶ οἱ πολέμιοι ἐγγὺς ἦσαν. ὁ μένων ὄπισθεν ἐκινδύνευεν. ὁ στρατηγὸς οὖν φοβεῖται μὴ οἱ ἄνδρες ἀπόλωνται· δέδοικε δὲ μὴ οὐ βούλωνται ἀναστῆναι. ἔλεγεν ὅτι πρὸς σωτηρίαν ἐκέλευε βαδίζειν, οὐ πρὸς ἑαυτοῦ κέρδος.","gloss":[{"greek":"ἀναμιμνῄσκει","english":"reminds"},{"greek":"ἔκαμνον","english":"were exhausted"},{"greek":"ὄπισθεν","english":"behind"},{"greek":"ἀπόλωνται","english":"may perish"},{"greek":"δέδοικε","english":"is afraid; supported perfect with present meaning"},{"greek":"μὴ οὐ βούλωνται","english":"that they may not be willing"}]},{"greek":"Ὅταν ὁ στρατιώτης κάμνῃ, βοηθείας δεῖται. ὃς ἂν τὸν ἑταῖρον καταλίπῃ, οὐ μόνον ἐκεῖνον ἀλλὰ καὶ τὸ κοινὸν βλάπτει. ταῦτα ὁ στρατηγὸς λέγει, ἵνα οἱ ἀκούοντες τὴν χρείαν ἐξετάζωσιν. οὐ μέντοι πᾶν ἔργον δίκαιόν ἐστιν ὅτι ὁ ποιῶν χρήσιμον αὐτὸ νομίζει. ζητῶμεν οὖν καὶ τὸν τρόπον καὶ τὴν αἰτίαν.","gloss":[{"greek":"Ὅταν","english":"whenever; with subjunctive"},{"greek":"κάμνῃ","english":"is exhausted; general clause"},{"greek":"ὃς ἂν","english":"whoever"},{"greek":"καταλίπῃ","english":"abandons; aorist subjunctive"},{"greek":"βλάπτει","english":"harms"},{"greek":"μέντοι","english":"however"}]},{"greek":"Ἐν τῇ διηγήσει οἱ στρατιῶται τῶν παλαιῶν πόνων μνημονεύουσιν, καὶ ὁ Ξενοφῶν τὴν ἑαυτοῦ γνώμην ἀπολογεῖται. ἡμεῖς δὲ δύο ἐρωτήσεις ποιούμεθα. τί φησιν ὁ κατήγορος, καὶ τί ἀποκρίνεται ὁ στρατηγός; ἔπειτα ἐρωτῶμεν τίς τὴν διήγησιν γράφει. ὁ γὰρ κρινόμενος καὶ ὁ γράφων ὁ αὐτός ἐστιν. τοῦτο οὔτε πάντα ψευδῆ ποιεῖ οὔτε πάντα ἀληθῆ ἀποδείκνυσιν.","gloss":[{"greek":"μνημονεύουσιν","english":"remember"},{"greek":"ἀπολογεῖται","english":"defends himself"},{"greek":"κατήγορος","english":"accuser"},{"greek":"κρινόμενος","english":"being judged"},{"greek":"ψευδῆ","english":"false"},{"greek":"ἀποδείκνυσιν","english":"proves"}]}],"translation":"The soldiers, saved from many dangers, had not escaped all their troubles. They still disputed about pay, food, and the generals’ actions. In the assembly some accused Xenophon of striking men. He did not leave, but wished to give an account. He therefore asks who the accuser is and when he suffered what he alleges.\n\nOne of the men stands up and says that he was struck by the general. Xenophon asks why. For it is not enough, he says, to say that you suffered something; one must also make clear what preceded the act. Those present listen to both. The charge is serious, but the response does not immediately resolve every difficulty. One must therefore examine carefully what is said.\n\nXenophon reminds the soldiers of the march. In winter many were exhausted, and the enemy were nearby. Anyone remaining behind was in danger. The general therefore fears that the men may perish; he is afraid that they may be unwilling to get up. He said that he ordered them to march for their safety, not for his own gain.\n\nWhenever a soldier is exhausted, he needs help. Whoever abandons his companion harms not only him but also the community. The general says these things so that the listeners may examine the need. Yet not every action is just because its doer considers it useful. Let us therefore investigate both the manner and the cause.\n\nIn the narrative the soldiers remember their former hardships, and Xenophon defends his own intention. We ask two questions: what does the accuser say, and what does the general reply? Then we ask who writes the account. For the man being judged and the writer are the same. This neither makes everything false nor proves everything true.\n","sourceCitation":"Xenophon, Anabasis 5.8.1–12 and selected 5.8.13–26. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1170/1170-h/1170-h.htm","notesMarkdown":"Based on Anabasis 5.8.1–26. Xenophon narrates accusations against himself and his own defense. The condensed dialogue and general clauses are teaching adaptations; his explanation is presented as his claim, not an independently established verdict."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ὁ στρατηγὸς λόγον δίδωσιν","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Anabasis 5.8.1–12 and selected 5.8.13–26. 254 Greek words in 5 paragraphs.","Based on Anabasis 5.8.1–26. Xenophon narrates accusations against himself and his own defense. The condensed dialogue and general clauses are teaching adaptations; his explanation is presented as his claim, not an independently established verdict.","Read once for the argument, then translate paragraph by paragraph. Use the glosses during the first pass; translate the closing paragraph continuously. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Οἱ στρατιῶται, ἐκ πολλῶν κινδύνων σωθέντες, οὐ πάντων τῶν κακῶν ἐπαύσαντο. ἔτι γὰρ περὶ μισθοῦ καὶ τροφῆς καὶ τῶν στρατηγῶν ἔργων διεφέροντο. ἐν τῇ ἐκκλησίᾳ τινὲς τὸν Ξενοφῶντα ᾐτιῶντο ὅτι ἄνδρας ἔπαισεν. ὁ δὲ οὐκ ἀπῆλθεν, ἀλλὰ λόγον δοῦναι ἤθελεν. ἐρωτᾷ οὖν τίς ἐστιν ὁ κατηγορῶν καὶ πότε ἔπαθεν ἃ λέγει.","gloss":[{"greek":"σωθέντες","english":"having been saved"},{"greek":"μισθοῦ","english":"pay"},{"greek":"ᾐτιῶντο","english":"were accusing"},{"greek":"ἔπαισεν","english":"struck"},{"greek":"λόγον δοῦναι","english":"to give an account"},{"greek":"κατηγορῶν","english":"accusing"}]},{"greek":"Εἷς τῶν ἀνδρῶν ἀναστὰς λέγει ὅτι ὑπὸ τοῦ στρατηγοῦ ἐπλήγη. ὁ Ξενοφῶν ἐρωτᾷ διὰ τί. οὐ γὰρ ἀρκεῖ, φησίν, εἰπεῖν ὅτι ἔπαθές τι· δεῖ καὶ τὰ πρὸ τοῦ ἔργου δηλοῦν. οἱ δὲ παρόντες ἀκούουσιν ἀμφοτέρων. ἡ μὲν αἰτία χαλεπή ἐστιν, ἡ δὲ ἀπόκρισις οὐ πᾶσαν ἀπορίαν εὐθὺς λύει. δεῖ οὖν ἀκριβῶς ἐξετάζειν τὰ λεγόμενα.","gloss":[{"greek":"ἀναστὰς","english":"having stood up"},{"greek":"ἐπλήγη","english":"was struck"},{"greek":"ἀρκεῖ","english":"it is enough"},{"greek":"ἔπαθές","english":"you suffered"},{"greek":"δηλοῦν","english":"to make clear"},{"greek":"ἀπόκρισις","english":"response"}]},{"greek":"Ὁ Ξενοφῶν τὴν πορείαν ἀναμιμνῄσκει τοὺς στρατιώτας. ἐν γὰρ τῷ χειμῶνι πολλοὶ ἔκαμνον, καὶ οἱ πολέμιοι ἐγγὺς ἦσαν. ὁ μένων ὄπισθεν ἐκινδύνευεν. ὁ στρατηγὸς οὖν φοβεῖται μὴ οἱ ἄνδρες ἀπόλωνται· δέδοικε δὲ μὴ οὐ βούλωνται ἀναστῆναι. ἔλεγεν ὅτι πρὸς σωτηρίαν ἐκέλευε βαδίζειν, οὐ πρὸς ἑαυτοῦ κέρδος.","gloss":[{"greek":"ἀναμιμνῄσκει","english":"reminds"},{"greek":"ἔκαμνον","english":"were exhausted"},{"greek":"ὄπισθεν","english":"behind"},{"greek":"ἀπόλωνται","english":"may perish"},{"greek":"δέδοικε","english":"he fears; perfect of δείδω with present meaning; read as a unit before perfect-system study"},{"greek":"μὴ οὐ βούλωνται","english":"that they may not be willing"}]},{"greek":"Ὅταν ὁ στρατιώτης κάμνῃ, βοηθείας δεῖται. ὃς ἂν τὸν ἑταῖρον καταλίπῃ, οὐ μόνον ἐκεῖνον ἀλλὰ καὶ τὸ κοινὸν βλάπτει. ταῦτα ὁ στρατηγὸς λέγει, ἵνα οἱ ἀκούοντες τὴν χρείαν ἐξετάζωσιν. οὐ μέντοι πᾶν ἔργον δίκαιόν ἐστιν ὅτι ὁ ποιῶν χρήσιμον αὐτὸ νομίζει. ζητῶμεν οὖν καὶ τὸν τρόπον καὶ τὴν αἰτίαν.","gloss":[{"greek":"Ὅταν","english":"whenever; with subjunctive"},{"greek":"κάμνῃ","english":"is exhausted; general clause"},{"greek":"ὃς ἂν","english":"whoever"},{"greek":"καταλίπῃ","english":"abandons; aorist subjunctive"},{"greek":"βλάπτει","english":"harms"},{"greek":"μέντοι","english":"however"}]},{"greek":"Ἐν τῇ διηγήσει οἱ στρατιῶται τῶν παλαιῶν πόνων μνημονεύουσιν, καὶ ὁ Ξενοφῶν τὴν ἑαυτοῦ γνώμην ἀπολογεῖται. ἡμεῖς δὲ δύο ἐρωτήσεις ποιούμεθα. τί φησιν ὁ κατήγορος, καὶ τί ἀποκρίνεται ὁ στρατηγός; ἔπειτα ἐρωτῶμεν τίς τὴν διήγησιν γράφει. ὁ γὰρ κρινόμενος καὶ ὁ γράφων ὁ αὐτός ἐστιν. τοῦτο οὔτε πάντα ψευδῆ ποιεῖ οὔτε πάντα ἀληθῆ ἀποδείκνυσιν.","gloss":[{"greek":"μνημονεύουσιν","english":"remember"},{"greek":"ἀπολογεῖται","english":"defends himself"},{"greek":"κατήγορος","english":"accuser"},{"greek":"κρινόμενος","english":"being judged"},{"greek":"ψευδῆ","english":"false"},{"greek":"ἀποδείκνυσιν","english":"proves"}]}],"translation":"The soldiers, saved from many dangers, had not escaped all their troubles. They still disputed about pay, food, and the generals’ actions. In the assembly some accused Xenophon of striking men. He did not leave, but wished to give an account. He therefore asks who the accuser is and when he suffered what he alleges.\n\nOne of the men stands up and says that he was struck by the general. Xenophon asks why. For it is not enough, he says, to say that you suffered something; one must also make clear what preceded the act. Those present listen to both. The charge is serious, but the response does not immediately resolve every difficulty. One must therefore examine carefully what is said.\n\nXenophon reminds the soldiers of the march. In winter many were exhausted, and the enemy were nearby. Anyone remaining behind was in danger. The general therefore fears that the men may perish; he is afraid that they may be unwilling to get up. He said that he ordered them to march for their safety, not for his own gain.\n\nWhenever a soldier is exhausted, he needs help. Whoever abandons his companion harms not only him but also the community. The general says these things so that the listeners may examine the need. Yet not every action is just because its doer considers it useful. Let us therefore investigate both the manner and the cause.\n\nIn the narrative the soldiers remember their former hardships, and Xenophon defends his own intention. We ask two questions: what does the accuser say, and what does the general reply? Then we ask who writes the account. For the man being judged and the writer are the same. This neither makes everything false nor proves everything true.\n","sourceCitation":"Xenophon, Anabasis 5.8.1–12 and selected 5.8.13–26. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1170/1170-h/1170-h.htm","notesMarkdown":"Based on Anabasis 5.8.1–26. Xenophon narrates accusations against himself and his own defense. The condensed dialogue and general clauses are teaching adaptations; his explanation is presented as his claim, not an independently established verdict."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-39' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 39 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
