DO $audit41$
DECLARE
  old_reading jsonb := $old${"title":"Πλούσιος ἄρχων ἢ εὐδαίμων πόλις;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hiero 9.1–11 and 11.1–15. 307 Greek words in 6 paragraphs.","Based on Hiero 9 and 11. Simonides’ recommendations are adapted into a connected argument. The dialogue does not establish that the historical Hiero implemented them; the final questions are course reflection.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Σιμωνίδης τῷ Ἱέρωνι περὶ ἀρχῆς διαλέγεται. ὁ μὲν Ἱέρων τύραννός ἐστιν, ὁ δὲ Σιμωνίδης ποιητής. οὐ μέντοι περὶ ᾠδῆς μόνον λέγουσιν, ἀλλὰ περὶ τοῦ βίου τοῦ ἄρχοντος. ὁ Ἱέρων πολλὰ κτήματα ἔχει, ἀλλὰ φοβεῖται καὶ οὐ πάντας τοὺς πλησίον πιστοὺς νομίζει. τὸ πλείω ἔχειν οὐ πάντως τὸ ἥδιον ζῆν παρέχει.","gloss":[{"greek":"τύραννός","english":"sole ruler, tyrant"},{"greek":"ᾠδῆς","english":"song"},{"greek":"πλησίον","english":"nearby"},{"greek":"πλείω","english":"more things; alternative accusative plural"},{"greek":"πάντως","english":"necessarily here"},{"greek":"ἥδιον","english":"more pleasantly"}]},{"greek":"Ὁ Σιμωνίδης ἄλλην ὁδὸν δείκνυσιν. ὁ ἄρχων μὴ μόνον τὸν ἴδιον οἶκον πλουσιώτερον ποιείτω, ἀλλὰ τὴν πόλιν ἀμείνω. ὅταν οἱ πολῖται καλῶς πράττωσιν, ὁ ἄρχων μείζονα τιμὴν λαμβάνει. τὰ γὰρ κοινὰ ἔργα πλείοσιν ἀνθρώποις ὠφέλιμά ἐστιν ἢ τὰ ἴδια κτήματα. οὐ τὸ μέγιστον ἀργύριον μόνον ἀλλὰ καὶ ἡ εὔνοια δύναμιν παρέχει.","gloss":[{"greek":"πλουσιώτερον","english":"wealthier"},{"greek":"ἀμείνω","english":"better; contracted comparative accusative"},{"greek":"μείζονα","english":"greater"},{"greek":"πλείοσιν","english":"to more; comparative dative plural"},{"greek":"ὠφέλιμά","english":"beneficial"},{"greek":"εὔνοια","english":"goodwill"}]},{"greek":"Ἐπιμελοῦ οὖν ὅπως οἱ πολῖται ἐργάσονται καὶ τὰς τέχνας ἀσκήσουσιν. ἆθλα δίδου τοῖς εὖ ποιοῦσιν, ἵνα καὶ οἱ ἄλλοι πονεῖν ἐθέλωσιν. οἱ μὲν γεωργοὶ τὴν γῆν βελτίω ποιήσουσιν, οἱ δὲ τὰ κοινὰ ἔργα κοσμήσουσιν. τὸ γὰρ ἆθλον πολλάκις μικρότερόν ἐστι τῆς δαπάνης ἣν οἱ ἀγωνιζόμενοι ἑκόντες ποιοῦνται. οὕτως ἡ φιλοτιμία πρὸς τὸ κοινὸν συμφέρον ἄγει.","gloss":[{"greek":"Ἐπιμελοῦ","english":"take care; imperative"},{"greek":"ἐργάσονται","english":"will work; future in object clause"},{"greek":"ἆθλα","english":"prizes"},{"greek":"βελτίω","english":"better; comparative accusative feminine"},{"greek":"δαπάνης","english":"expense"},{"greek":"φιλοτιμία","english":"ambition for honor"}]},{"greek":"Σκόπει δὲ ὅπως οἱ φύλακες τοὺς πολίτας φυλάξουσιν, οὐ μόνον σέ. ὁ γὰρ φόβος οὐχ ὁμοῖός ἐστι τῇ φιλίᾳ. ὅταν οἱ ἄνθρωποι τὴν δύναμιν πρὸς αὑτοὺς ὠφέλιμον ὁρῶσιν, ἧττον αὐτὴν φοβοῦνται. ὁ ἄριστος ἄρχων οὐ τῷ ἰδιώτῃ περὶ πλούτου ἀγωνίζεται, ἀλλὰ ταῖς ἄλλαις πόλεσι περὶ τῆς τῶν πολιτῶν εὐδαιμονίας.","gloss":[{"greek":"Σκόπει","english":"see to it"},{"greek":"φυλάξουσιν","english":"will protect"},{"greek":"αὑτοὺς","english":"themselves"},{"greek":"ἧττον","english":"less"},{"greek":"ἰδιώτῃ","english":"private individual"},{"greek":"εὐδαιμονίας","english":"well-being"}]},{"greek":"Ταῦτα ὁ Σιμωνίδης συμβουλεύει. ὁ δὲ ἀναγνώστης ζητεῖ τίς τῶν προτάσεων ὠφελεῖται. ὁ γεωργὸς λαμβάνει τιμήν, ἡ πόλις πλείονα ἔργα, ὁ δὲ ἄρχων ἀσφαλεστέραν ἀρχήν. ἀλλὰ τίς κρίνει τὸν ἄρχοντα; τίς τῷ ἀδικούμενῳ βοηθεῖ; ταῦτα δεῖ ἐξετάζειν πρὶν τὴν εὐεργεσίαν τῇ δικαιοσύνῃ ταὐτὴν νομίζειν. ἡ γὰρ τῶν κτημάτων αὔξησις οὐ πᾶσαν περὶ τοῦ δικαίου ἐρώτησιν λύει.","gloss":[{"greek":"συμβουλεύει","english":"advises"},{"greek":"προτάσεων","english":"proposals"},{"greek":"ἀσφαλεστέραν","english":"safer"},{"greek":"ἀδικούμενῳ","english":"person being wronged"},{"greek":"εὐεργεσίαν","english":"benefaction"},{"greek":"αὔξησις","english":"increase"}]},{"greek":"Τὸν λόγον οὖν ὡς συμβουλὴν ἀναγινώσκωμεν, οὐχ ὡς μαρτυρίαν ὅτι πάντα οὕτως ἐγένετο. ὁ συγγραφεὺς δύο φωνὰς ἡμῖν παρέχει, ἵνα συγκρίνωμεν τὸ φοβεῖσθαι καὶ τὸ φιλεῖσθαι. ἡ τοῦ ἄρχοντος εὐδαιμονία πρὸς τὴν τῆς πόλεως εὐδαιμονίαν ἀναφέρεται· ἀλλὰ καὶ τὸ τῆς ἐξουσίας μέτρον ἔτι ζητητέον ἐστίν.","gloss":[{"greek":"συμβουλὴν","english":"advice"},{"greek":"μαρτυρίαν","english":"testimony"},{"greek":"συγκρίνωμεν","english":"may compare"},{"greek":"φιλεῖσθαι","english":"to be loved"},{"greek":"ἀναφέρεται","english":"is related"},{"greek":"ζητητέον","english":"requiring inquiry; supported verbal adjective"}]}],"translation":"Simonides discusses rule with Hiero. Hiero is a tyrant, Simonides a poet. Yet they speak not only about song but about the ruler’s life. Hiero has many possessions, but he is afraid and does not consider everyone nearby trustworthy. Having more does not necessarily provide a more pleasant life.\n\nSimonides points out another path. Let the ruler make not only his own household wealthier but the city better. Whenever the citizens prosper, the ruler receives greater honor. For public works benefit more people than private possessions do. Not only the greatest amount of silver but also goodwill provides power.\n\nTake care, then, that the citizens will work and practice their crafts. Give prizes to those doing well, so that others too may be willing to labor. Farmers will improve the land, while others will adorn public works. For the prize is often smaller than the expense that competitors willingly incur. In this way ambition leads toward the common advantage.\n\nSee that the guards will protect the citizens, not only you. Fear is not the same as friendship. Whenever people see power as beneficial to themselves, they fear it less. The best ruler does not compete with a private individual in wealth, but with other cities over the well-being of his citizens.\n\nSimonides gives this advice. The reader asks who benefits from the proposals. The farmer receives honor, the city more works, and the ruler a safer rule. But who judges the ruler? Who helps the person wronged? We must examine these questions before treating benefaction as identical with justice. For an increase in possessions does not resolve every question about what is just.\n\nLet us therefore read the argument as advice, not as testimony that everything happened in this way. The author supplies two voices so that we may compare being feared and being loved. The ruler’s well-being is related to the city’s well-being; but the measure of his authority still requires examination.\n","sourceCitation":"Xenophon, Hiero 9.1–11 and 11.1–15. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1175/1175-h/1175-h.htm","notesMarkdown":"Based on Hiero 9 and 11. Simonides’ recommendations are adapted into a connected argument. The dialogue does not establish that the historical Hiero implemented them; the final questions are course reflection."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Πλούσιος ἄρχων ἢ εὐδαίμων πόλις;","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hiero 9.1–11 and 11.1–15. 307 Greek words in 6 paragraphs.","Based on Hiero 9 and 11. Simonides’ recommendations are adapted into a connected argument. The dialogue does not establish that the historical Hiero implemented them; the final questions are course reflection.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Σιμωνίδης τῷ Ἱέρωνι περὶ ἀρχῆς διαλέγεται. ὁ μὲν Ἱέρων τύραννός ἐστιν, ὁ δὲ Σιμωνίδης ποιητής. οὐ μέντοι περὶ ᾠδῆς μόνον λέγουσιν, ἀλλὰ περὶ τοῦ βίου τοῦ ἄρχοντος. ὁ Ἱέρων πολλὰ κτήματα ἔχει, ἀλλὰ φοβεῖται καὶ οὐ πάντας τοὺς πλησίον πιστοὺς νομίζει. τὸ πλείω ἔχειν οὐ πάντως τὸ ἥδιον ζῆν παρέχει.","gloss":[{"greek":"τύραννός","english":"sole ruler, tyrant"},{"greek":"ᾠδῆς","english":"song"},{"greek":"πλησίον","english":"nearby"},{"greek":"πλείω","english":"more things; alternative accusative plural"},{"greek":"πάντως","english":"necessarily here"},{"greek":"ἥδιον","english":"more pleasantly"}]},{"greek":"Ὁ Σιμωνίδης ἄλλην ὁδὸν δείκνυσιν. ὁ ἄρχων μὴ μόνον τὸν ἴδιον οἶκον πλουσιώτερον ποιείτω, ἀλλὰ τὴν πόλιν ἀμείνω. ὅταν οἱ πολῖται καλῶς πράττωσιν, ὁ ἄρχων μείζονα τιμὴν λαμβάνει. τὰ γὰρ κοινὰ ἔργα πλείοσιν ἀνθρώποις ὠφέλιμά ἐστιν ἢ τὰ ἴδια κτήματα. οὐ τὸ μέγιστον ἀργύριον μόνον ἀλλὰ καὶ ἡ εὔνοια δύναμιν παρέχει.","gloss":[{"greek":"πλουσιώτερον","english":"wealthier"},{"greek":"ἀμείνω","english":"better; contracted comparative accusative"},{"greek":"μείζονα","english":"greater"},{"greek":"πλείοσιν","english":"to more; comparative dative plural"},{"greek":"ὠφέλιμά","english":"beneficial"},{"greek":"εὔνοια","english":"goodwill"}]},{"greek":"Ἐπιμελοῦ οὖν ὅπως οἱ πολῖται ἐργάσονται καὶ τὰς τέχνας ἀσκήσουσιν. ἆθλα δίδου τοῖς εὖ ποιοῦσιν, ἵνα καὶ οἱ ἄλλοι πονεῖν ἐθέλωσιν. οἱ μὲν γεωργοὶ τὴν γῆν βελτίω ποιήσουσιν, οἱ δὲ τὰ κοινὰ ἔργα κοσμήσουσιν. τὸ γὰρ ἆθλον πολλάκις μικρότερόν ἐστι τῆς δαπάνης ἣν οἱ ἀγωνιζόμενοι ἑκόντες ποιοῦνται. οὕτως ἡ φιλοτιμία πρὸς τὸ κοινὸν συμφέρον ἄγει.","gloss":[{"greek":"Ἐπιμελοῦ","english":"take care; imperative"},{"greek":"ἐργάσονται","english":"will work; future in object clause"},{"greek":"ἆθλα","english":"prizes"},{"greek":"βελτίω","english":"better; comparative accusative feminine"},{"greek":"δαπάνης","english":"expense"},{"greek":"φιλοτιμία","english":"ambition for honor"}]},{"greek":"Σκόπει δὲ ὅπως οἱ φύλακες τοὺς πολίτας φυλάξουσιν, οὐ μόνον σέ. ὁ γὰρ φόβος οὐχ ὁμοῖός ἐστι τῇ φιλίᾳ. ὅταν οἱ ἄνθρωποι τὴν δύναμιν πρὸς αὑτοὺς ὠφέλιμον ὁρῶσιν, ἧττον αὐτὴν φοβοῦνται. ὁ ἄριστος ἄρχων οὐ τῷ ἰδιώτῃ περὶ πλούτου ἀγωνίζεται, ἀλλὰ ταῖς ἄλλαις πόλεσι περὶ τῆς τῶν πολιτῶν εὐδαιμονίας.","gloss":[{"greek":"Σκόπει","english":"see to it"},{"greek":"φυλάξουσιν","english":"will protect"},{"greek":"αὑτοὺς","english":"themselves"},{"greek":"ἧττον","english":"less"},{"greek":"ἰδιώτῃ","english":"private individual"},{"greek":"εὐδαιμονίας","english":"well-being"}]},{"greek":"Ταῦτα ὁ Σιμωνίδης συμβουλεύει. ὁ δὲ ἀναγνώστης ζητεῖ τίς τῶν προτάσεων ὠφελεῖται. ὁ γεωργὸς λαμβάνει τιμήν, ἡ πόλις πλείονα ἔργα, ὁ δὲ ἄρχων ἀσφαλεστέραν ἀρχήν. ἀλλὰ τίς κρίνει τὸν ἄρχοντα; τίς τῷ ἀδικούμενῳ βοηθεῖ; ταῦτα δεῖ ἐξετάζειν πρὶν τὴν εὐεργεσίαν τῇ δικαιοσύνῃ ταὐτὴν νομίζειν. ἡ γὰρ τῶν κτημάτων αὔξησις οὐ πᾶσαν περὶ τοῦ δικαίου ἐρώτησιν λύει.","gloss":[{"greek":"συμβουλεύει","english":"advises"},{"greek":"προτάσεων","english":"proposals"},{"greek":"ἀσφαλεστέραν","english":"safer"},{"greek":"ἀδικούμενῳ","english":"person being wronged"},{"greek":"εὐεργεσίαν","english":"benefaction"},{"greek":"αὔξησις","english":"increase"}]},{"greek":"Τὸν λόγον οὖν ὡς συμβουλὴν ἀναγινώσκωμεν, οὐχ ὡς μαρτυρίαν ὅτι πάντα οὕτως ἐγένετο. ὁ συγγραφεὺς δύο φωνὰς ἡμῖν παρέχει, ἵνα συγκρίνωμεν τὸ φοβεῖσθαι καὶ τὸ φιλεῖσθαι. ἡ τοῦ ἄρχοντος εὐδαιμονία πρὸς τὴν τῆς πόλεως εὐδαιμονίαν ἀναφέρεται· ἀλλὰ καὶ τὸ τῆς ἐξουσίας μέτρον ἔτι ζητητέον ἐστίν.","gloss":[{"greek":"συμβουλὴν","english":"advice"},{"greek":"μαρτυρίαν","english":"testimony"},{"greek":"συγκρίνωμεν","english":"may compare"},{"greek":"φιλεῖσθαι","english":"to be loved"},{"greek":"ἀναφέρεται","english":"is related"},{"greek":"ζητητέον","english":"requiring inquiry; supported verbal adjective"},{"greek":"ζητητέον ἐστίν","english":"must be examined; whole-phrase preview of the verbal adjective in -τέος, studied in Lesson 44"}]}],"translation":"Simonides discusses rule with Hiero. Hiero is a tyrant, Simonides a poet. Yet they speak not only about song but about the ruler’s life. Hiero has many possessions, but he is afraid and does not consider everyone nearby trustworthy. Having more does not necessarily provide a more pleasant life.\n\nSimonides points out another path. Let the ruler make not only his own household wealthier but the city better. Whenever the citizens prosper, the ruler receives greater honor. For public works benefit more people than private possessions do. Not only the greatest amount of silver but also goodwill provides power.\n\nTake care, then, that the citizens will work and practice their crafts. Give prizes to those doing well, so that others too may be willing to labor. Farmers will improve the land, while others will adorn public works. For the prize is often smaller than the expense that competitors willingly incur. In this way ambition leads toward the common advantage.\n\nSee that the guards will protect the citizens, not only you. Fear is not the same as friendship. Whenever people see power as beneficial to themselves, they fear it less. The best ruler does not compete with a private individual in wealth, but with other cities over the well-being of his citizens.\n\nSimonides gives this advice. The reader asks who benefits from the proposals. The farmer receives honor, the city more works, and the ruler a safer rule. But who judges the ruler? Who helps the person wronged? We must examine these questions before treating benefaction as identical with justice. For an increase in possessions does not resolve every question about what is just.\n\nLet us therefore read the argument as advice, not as testimony that everything happened in this way. The author supplies two voices so that we may compare being feared and being loved. The ruler’s well-being is related to the city’s well-being; but the measure of his authority still requires examination.\n","sourceCitation":"Xenophon, Hiero 9.1–11 and 11.1–15. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1175/1175-h/1175-h.htm","notesMarkdown":"Based on Hiero 9 and 11. Simonides’ recommendations are adapted into a connected argument. The dialogue does not establish that the historical Hiero implemented them; the final questions are course reflection."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-41' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 41 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
$audit41$;
DO $audit42$
DECLARE
  old_reading jsonb := $old${"title":"Ὁ νόμος καὶ τὸ δίκαιον","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 4.4.5–18; brief extension from 4.4.19–25. 305 Greek words in 6 paragraphs.","Based on Memorabilia 4.4.5–25. The sequence of challenge, lawful conduct, changing laws, and unwritten obligations follows the source. Wishes and potential statements in the final paragraphs are explicitly course reflection, not quotations from Hippias or Socrates.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Ἱππίας εἰς τὰς Ἀθήνας ἥκει καὶ Σωκράτει διαλέγεται. θαυμάζει ὅτι ὁ Σωκράτης ἔτι περὶ τῶν αὐτῶν λέγει. ὁ δὲ οὐκ αἰσχύνεται ταὐτὰ ζητῶν· οὐ γὰρ τὸ καινὸν μόνον ἀλλὰ τὸ ἀληθὲς σκοπεῖ. ὁ Ἱππίας ἀξιοῖ αὐτὸν μὴ μόνον τοὺς ἄλλους ἐρωτᾶν, ἀλλὰ καὶ τὴν ἑαυτοῦ γνώμην περὶ δικαιοσύνης εἰπεῖν.","gloss":[{"greek":"ἥκει","english":"has arrived"},{"greek":"αἰσχύνεται","english":"is ashamed"},{"greek":"καινὸν","english":"new thing"},{"greek":"ἀξιοῖ","english":"asks, expects"},{"greek":"ἐρωτᾶν","english":"to question"},{"greek":"γνώμην","english":"view"}]},{"greek":"Ὁ Σωκράτης πρῶτον τὸν βίον αὑτοῦ παράδειγμα παρέχει. οὐ ψευδῆ μαρτυρεῖ οὐδὲ τοὺς φίλους εἰς στάσιν ἄγει. ὁ δὲ Ἱππίας λόγον σαφέστερον ζητεῖ· οὐ γὰρ ἀρκεῖ λέγειν ἃ ὁ δίκαιος οὐ ποιεῖ. τί οὖν ποιεῖ; ὁ Σωκράτης τὸ νόμιμον δίκαιον εἶναί φησιν. οὕτως ἐκ τῶν ἔργων εἰς τὸν ὁρισμὸν ὁ λόγος μεταβαίνει.","gloss":[{"greek":"αὑτοῦ","english":"his own"},{"greek":"μαρτυρεῖ","english":"bears witness"},{"greek":"στάσιν","english":"faction"},{"greek":"σαφέστερον","english":"clearer"},{"greek":"νόμιμον","english":"lawful"},{"greek":"ὁρισμὸν","english":"definition"}]},{"greek":"Ὁ Ἱππίας ἐρωτᾷ πῶς τοῦτο λέγει. οἱ γὰρ πολῖται τοὺς νόμους τίθενται, ἔπειτα δὲ μεταβάλλουσιν. πῶς οὖν τοῖς νόμοις πιστεύωμεν, ὅταν οἱ θέμενοι αὐτοὶ μὴ μένωσιν ἐν τοῖς αὐτοῖς; ἡ ἐρώτησις οὐ μικρά ἐστιν. ἄλλο γάρ ἐστι νόμῳ πείθεσθαι, ἄλλο δὲ τὸν νόμον ἀεὶ βέλτιστον νομίζειν. τὴν διαφορὰν ταύτην ὁ ἀναγνώστης ἐξετάζει.","gloss":[{"greek":"μεταβάλλουσιν","english":"change"},{"greek":"θέμενοι","english":"having established"},{"greek":"μένωσιν","english":"remain; subjunctive"},{"greek":"βέλτιστον","english":"best"},{"greek":"διαφορὰν","english":"distinction"}]},{"greek":"Ὁ Σωκράτης τὴν εὐνομίαν ἐπαινεῖ. οἱ γὰρ νόμοι τοὺς πολίτας πρὸς κοινὰ ἔργα συνάγουσιν, καὶ ἡ ὁμόνοια τὴν πόλιν ἰσχυροτέραν ποιεῖ. οὐ μόνον δὲ περὶ τῶν γεγραμμένων λέγει· ἐρωτᾷ καὶ περὶ ἀγράφων νόμων. τὸ τοὺς γονέας τιμᾶν καὶ τὸ χάριν ἀποδιδόναι παραδείγματα παρέχει. τούτους τοὺς νόμους πρὸς τοὺς θεοὺς ἀναφέρει.","gloss":[{"greek":"εὐνομίαν","english":"good order under law"},{"greek":"συνάγουσιν","english":"bring together"},{"greek":"ὁμόνοια","english":"concord"},{"greek":"γεγραμμένων","english":"written rules; supported perfect participle"},{"greek":"ἀγράφων","english":"unwritten"},{"greek":"χάριν ἀποδιδόναι","english":"to return kindness"}]},{"greek":"Νῦν ἡμεῖς τὸν λόγον ἐξετάζοντες εὐχὰς καὶ δυνατὰ λέγομεν. εἴθε οἱ πολῖται δικαίως κρίνοιεν. εἴθε μὴ τὸ κέρδος τοῦ δικαίου προτιμῷεν. ὁ δίκαιος ἀνὴρ οὐχ ἁπλῶς τῷ ἰσχυρῷ πείθοιτο ἄν· πρῶτον γὰρ τὸ κελευόμενον ἐξετάζοι ἄν. οὐ λέγομεν ὅτι πάντα ταῦτα γίγνεται, ἀλλὰ τί εὐχόμεθα καὶ τί δυνατὸν εἶναι νομίζομεν.","gloss":[{"greek":"εἴθε","english":"if only, may"},{"greek":"κρίνοιεν","english":"may they judge; optative wish"},{"greek":"προτιμῷεν","english":"may they prefer; contract optative"},{"greek":"πείθοιτο ἄν","english":"might obey"},{"greek":"ἐξετάζοι ἄν","english":"might examine"},{"greek":"εὐχόμεθα","english":"we wish"}]},{"greek":"Ἡ περὶ δικαιοσύνης ζήτησις οὐ τελευτᾷ ἑνὶ λόγῳ. ὁ ἀναγνώστης μνημονεύει τοῦ Σωκράτους πρὸς τὴν ἄνομον ψῆφον ἀντειπόντος. ἐκεῖνος νόμῳ βοηθεῖν ἐβούλετο, οὐ τῇ τῶν πολλῶν ὀργῇ. νόμος δὲ καὶ τὸ ὑπὸ δυνατοῦ ἀνδρὸς κελευόμενον οὐκ ἀεὶ ταὐτόν ἐστιν. τοῦτο σκοποῖμεν ἄν, ἵνα μὴ τὴν τῆς πόλεως δύναμιν ἄνευ κρίσεως ἐπαινῶμεν.","gloss":[{"greek":"τελευτᾷ","english":"ends"},{"greek":"ἀντειπόντος","english":"having objected"},{"greek":"ἄνομον","english":"unlawful"},{"greek":"κελευόμενον","english":"what is commanded"},{"greek":"σκοποῖμεν ἄν","english":"we might examine"},{"greek":"ἄνευ","english":"without; with genitive"}]}],"translation":"Hippias arrives in Athens and converses with Socrates. He is surprised that Socrates still speaks about the same things. Socrates is not ashamed of investigating the same matters; he considers not only what is new but what is true. Hippias asks him not merely to question others but to state his own view about justice.\n\nSocrates first offers his own life as an example. He does not give false testimony or lead friends into faction. Hippias seeks a clearer explanation: it is not enough to say what the just person does not do. What, then, does he do? Socrates says that what is lawful is just. Thus the argument moves from actions to a definition.\n\nHippias asks how he can say this. Citizens establish laws and then change them. How, then, should we trust laws whenever those who established them do not themselves remain with the same rules? The question is substantial. Obeying a law is one thing, considering it always the best another. The reader examines this distinction.\n\nSocrates praises good order under law. Laws bring citizens together for common tasks, and concord makes the city stronger. He speaks not only about written rules; he also asks about unwritten laws. He offers honoring parents and returning kindness as examples. He refers these laws to the gods.\n\nNow, in examining the argument, we express wishes and possibilities. May the citizens judge justly. May they not prefer gain to justice. A just person might not simply obey the powerful; he might first examine the command. We are not saying that all this happens, but what we wish and what we consider possible.\n\nThe inquiry about justice does not end with a single statement. The reader remembers Socrates objecting to the unlawful vote. He wished to defend law, not the anger of the majority. Law and what a powerful man commands are not always the same. We might examine this so that we do not praise the city’s power without judgment.\n","sourceCitation":"Xenophon, Memorabilia 4.4.5–18; brief extension from 4.4.19–25. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm","notesMarkdown":"Based on Memorabilia 4.4.5–25. The sequence of challenge, lawful conduct, changing laws, and unwritten obligations follows the source. Wishes and potential statements in the final paragraphs are explicitly course reflection, not quotations from Hippias or Socrates."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ὁ νόμος καὶ τὸ δίκαιον","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Memorabilia 4.4.5–18; brief extension from 4.4.19–25. 328 Greek words in 6 paragraphs.","Based on Memorabilia 4.4.5–25. The sequence of challenge, lawful conduct, changing laws, and unwritten obligations follows the source. Wishes and potential statements in the final paragraphs are explicitly course reflection, not quotations from Hippias or Socrates.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Ὁ Ἱππίας εἰς τὰς Ἀθήνας ἥκει καὶ Σωκράτει διαλέγεται. θαυμάζει ὅτι ὁ Σωκράτης ἔτι περὶ τῶν αὐτῶν λέγει. ὁ δὲ οὐκ αἰσχύνεται ταὐτὰ ζητῶν· οὐ γὰρ τὸ καινὸν μόνον ἀλλὰ τὸ ἀληθὲς σκοπεῖ. ὁ Ἱππίας ἀξιοῖ αὐτὸν μὴ μόνον τοὺς ἄλλους ἐρωτᾶν, ἀλλὰ καὶ τὴν ἑαυτοῦ γνώμην περὶ δικαιοσύνης εἰπεῖν.","gloss":[{"greek":"ἥκει","english":"has arrived"},{"greek":"αἰσχύνεται","english":"is ashamed"},{"greek":"καινὸν","english":"new thing"},{"greek":"ἀξιοῖ","english":"asks, expects"},{"greek":"ἐρωτᾶν","english":"to question"},{"greek":"γνώμην","english":"view"}]},{"greek":"Ὁ Σωκράτης πρῶτον τὸν βίον αὑτοῦ παράδειγμα παρέχει. οὐ ψευδῆ μαρτυρεῖ οὐδὲ τοὺς φίλους εἰς στάσιν ἄγει. ὁ δὲ Ἱππίας λόγον σαφέστερον ζητεῖ· οὐ γὰρ ἀρκεῖ λέγειν ἃ ὁ δίκαιος οὐ ποιεῖ. τί οὖν ποιεῖ; ὁ Σωκράτης τὸ νόμιμον δίκαιον εἶναί φησιν. οὕτως ἐκ τῶν ἔργων εἰς τὸν ὁρισμὸν ὁ λόγος μεταβαίνει.","gloss":[{"greek":"αὑτοῦ","english":"his own"},{"greek":"μαρτυρεῖ","english":"bears witness"},{"greek":"στάσιν","english":"faction"},{"greek":"σαφέστερον","english":"clearer"},{"greek":"νόμιμον","english":"lawful"},{"greek":"ὁρισμὸν","english":"definition"}]},{"greek":"Ὁ Ἱππίας ἐρωτᾷ πῶς τοῦτο λέγει. οἱ γὰρ πολῖται τοὺς νόμους τίθενται, ἔπειτα δὲ μεταβάλλουσιν. πῶς οὖν τοῖς νόμοις πιστεύωμεν, ὅταν οἱ θέμενοι αὐτοὶ μὴ μένωσιν ἐν τοῖς αὐτοῖς; ἡ ἐρώτησις οὐ μικρά ἐστιν. ἄλλο γάρ ἐστι νόμῳ πείθεσθαι, ἄλλο δὲ τὸν νόμον ἀεὶ βέλτιστον νομίζειν. τὴν διαφορὰν ταύτην ὁ ἀναγνώστης ἐξετάζει.","gloss":[{"greek":"μεταβάλλουσιν","english":"change"},{"greek":"θέμενοι","english":"having established"},{"greek":"μένωσιν","english":"remain; subjunctive"},{"greek":"βέλτιστον","english":"best"},{"greek":"διαφορὰν","english":"distinction"}]},{"greek":"Ὁ Σωκράτης τὴν εὐνομίαν ἐπαινεῖ. οἱ γὰρ νόμοι τοὺς πολίτας πρὸς κοινὰ ἔργα συνάγουσιν, καὶ ἡ ὁμόνοια τὴν πόλιν ἰσχυροτέραν ποιεῖ. οὐ μόνον δὲ περὶ τῶν γεγραμμένων λέγει· ἐρωτᾷ καὶ περὶ ἀγράφων νόμων. τὸ τοὺς γονέας τιμᾶν καὶ τὸ χάριν ἀποδιδόναι παραδείγματα παρέχει. τούτους τοὺς νόμους πρὸς τοὺς θεοὺς ἀναφέρει.","gloss":[{"greek":"εὐνομίαν","english":"good order under law"},{"greek":"συνάγουσιν","english":"bring together"},{"greek":"ὁμόνοια","english":"concord"},{"greek":"γεγραμμένων","english":"written rules; supported perfect participle"},{"greek":"ἀγράφων","english":"unwritten"},{"greek":"χάριν ἀποδιδόναι","english":"to return kindness"},{"greek":"τῶν γεγραμμένων","english":"the written laws; perfect passive participle; supported reading vocabulary"}]},{"greek":"Νῦν ἡμεῖς τὸν λόγον ἐξετάζοντες εὐχὰς καὶ δυνατὰ λέγομεν. εἴθε οἱ πολῖται δικαίως κρίνοιεν. εἴθε μὴ τὸ κέρδος τοῦ δικαίου προτιμῷεν. ὁ δίκαιος ἀνὴρ οὐχ ἁπλῶς τῷ ἰσχυρῷ πείθοιτο ἄν· πρῶτον γὰρ τὸ κελευόμενον ἐξετάζοι ἄν. οὐ λέγομεν ὅτι πάντα ταῦτα γίγνεται, ἀλλὰ τί εὐχόμεθα καὶ τί δυνατὸν εἶναι νομίζομεν.","gloss":[{"greek":"εἴθε","english":"if only, may"},{"greek":"κρίνοιεν","english":"may they judge; optative wish"},{"greek":"προτιμῷεν","english":"may they prefer; contract optative"},{"greek":"πείθοιτο ἄν","english":"might obey"},{"greek":"ἐξετάζοι ἄν","english":"might examine"},{"greek":"εὐχόμεθα","english":"we wish"}]},{"greek":"Ἡ περὶ δικαιοσύνης ζήτησις οὐ τελευτᾷ ἑνὶ λόγῳ. ὁ ἀναγνώστης μνημονεύει τοῦ Σωκράτους πρὸς τὴν ἄνομον ψῆφον ἀντειπόντος. ἐκεῖνος νόμῳ βοηθεῖν ἐβούλετο, οὐ τῇ τῶν πολλῶν ὀργῇ. νόμος δὲ καὶ τὸ ὑπὸ δυνατοῦ ἀνδρὸς κελευόμενον οὐκ ἀεὶ ταὐτόν ἐστιν. τοῦτο σκοποῖμεν ἄν, ἵνα μὴ τὴν τῆς πόλεως δύναμιν ἄνευ κρίσεως ἐπαινῶμεν. Ἐν ἀσκήσει συγκρίνομεν· ὁ Σωκράτης τὸ κελευόμενον ἐξετάζει, ἵνα οἱ πολῖται δικαίως κρίνωσιν· ὁ Σωκράτης τὸ κελευόμενον ἐξήταζεν, ἵνα οἱ πολῖται δικαίως κρίνοιεν.","gloss":[{"greek":"τελευτᾷ","english":"ends"},{"greek":"ἀντειπόντος","english":"having objected"},{"greek":"ἄνομον","english":"unlawful"},{"greek":"κελευόμενον","english":"what is commanded"},{"greek":"σκοποῖμεν ἄν","english":"we might examine"},{"greek":"ἄνευ","english":"without; with genitive"},{"greek":"κρίνωσιν","english":"may judge; present subjunctive in purpose after a present main verb"},{"greek":"ἐξήταζεν","english":"was examining; imperfect"},{"greek":"κρίνοιεν","english":"might judge; present optative in purpose after a past main verb; the subjunctive could also be retained"}]}],"translation":"Hippias arrives in Athens and converses with Socrates. He is surprised that Socrates still speaks about the same things. Socrates is not ashamed of investigating the same matters; he considers not only what is new but what is true. Hippias asks him not merely to question others but to state his own view about justice.\n\nSocrates first offers his own life as an example. He does not give false testimony or lead friends into faction. Hippias seeks a clearer explanation: it is not enough to say what the just person does not do. What, then, does he do? Socrates says that what is lawful is just. Thus the argument moves from actions to a definition.\n\nHippias asks how he can say this. Citizens establish laws and then change them. How, then, should we trust laws whenever those who established them do not themselves remain with the same rules? The question is substantial. Obeying a law is one thing, considering it always the best another. The reader examines this distinction.\n\nSocrates praises good order under law. Laws bring citizens together for common tasks, and concord makes the city stronger. He speaks not only about written rules; he also asks about unwritten laws. He offers honoring parents and returning kindness as examples. He refers these laws to the gods.\n\nNow, in examining the argument, we express wishes and possibilities. May the citizens judge justly. May they not prefer gain to justice. A just person might not simply obey the powerful; he might first examine the command. We are not saying that all this happens, but what we wish and what we consider possible.\n\nThe inquiry about justice does not end with a single statement. The reader remembers Socrates objecting to the unlawful vote. He wished to defend law, not the anger of the majority. Law and what a powerful man commands are not always the same. We might examine this so that we do not praise the city’s power without judgment. In an exercise we compare: Socrates examines the command so that the citizens may judge fairly; Socrates was examining the command so that the citizens might judge fairly.\n","sourceCitation":"Xenophon, Memorabilia 4.4.5–18; brief extension from 4.4.19–25. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1177/1177-h/1177-h.htm","notesMarkdown":"Based on Memorabilia 4.4.5–25. The sequence of challenge, lawful conduct, changing laws, and unwritten obligations follows the source. Wishes and potential statements in the final paragraphs are explicitly course reflection, not quotations from Hippias or Socrates."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-42' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 42 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
