DO $audit43$
DECLARE
  old_reading jsonb := $old${"title":"Ὅταν ὁ φόβος τὸν νόμον λύῃ","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hellenica 2.3.50–56, with context summarized from 2.3.15–20. 307 Greek words in 6 paragraphs.","Based on Hellenica 2.3.50–56, with context from 2.3.15–20. The indirect questions and reporting frames are teaching compositions. Theramenes was himself an oligarch; scrutiny of his seizure does not absolve his earlier political conduct.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Μετὰ τὴν τῶν Ἀθηναίων ἧτταν οἱ Τριάκοντα τῆς πόλεως ἦρχον. ἐν δὲ τούτοις Κριτίας καὶ Θηραμένης ἦσαν. οὐ περὶ πάντων ὡμολόγουν· ὁ Θηραμένης τὴν ἀρχὴν στενωτέραν τοῦ προσήκοντος ἐνόμιζεν, ὁ δὲ Κριτίας αὐτὸν ἐμπόδιον ἑαυτῷ ἡγεῖτο. οἱ μὲν γὰρ ἄρχοντες πλείω δύναμιν ἐζήτουν, οἱ δὲ πολῖται ἐφοβοῦντο μὴ ἕκαστος αὐτῶν ὁ ἑξῆς ἀπολοίτο.","gloss":[{"greek":"ἧτταν","english":"defeat"},{"greek":"Τριάκοντα","english":"the Thirty"},{"greek":"στενωτέραν","english":"narrower"},{"greek":"ἐμπόδιον","english":"obstacle"},{"greek":"ἑξῆς","english":"next"},{"greek":"ἀπολοίτο","english":"might perish; optative after past fear"}]},{"greek":"Κατάλογος τρισχιλίων πολιτῶν ἦν. τοὺς μὲν ἐν τῷ καταλόγῳ ὄντας τὴν βουλὴν πρὸ τοῦ θανάτου κρίνειν ἔδει, τοὺς δὲ ἔξω οἱ Τριάκοντα ἀποκτείνειν ἐδύναντο. ὁ κατάλογος οὖν οὐκ ἦν τῶν ὀνομάτων γραφὴ μόνον, ἀλλὰ πρὸς τὴν ἀσφάλειαν διαφορὰν ἐποίει. ὁ Θηραμένης τῶν ἐν τῷ καταλόγῳ ἦν καὶ τὴν κρίσιν τῆς βουλῆς ἠξίου.","gloss":[{"greek":"κατάλογος","english":"list"},{"greek":"τρισχιλίων","english":"three thousand"},{"greek":"βουλὴ","english":"council"},{"greek":"ἔξω","english":"outside"},{"greek":"ἀσφάλειαν","english":"safety"},{"greek":"ἠξίου","english":"claimed, demanded"}]},{"greek":"Ὁ Κριτίας, ὁρῶν τὴν βουλὴν εὐμενῶς πρὸς Θηραμένην ἔχουσαν, οὐκ ἐβούλετο κινδυνεύειν τὴν ψῆφον. ἔνοπλοι δὲ ἄνδρες παρῆσαν. ἔλεγεν ὅτι τοῦτο τῶν ἀρχόντων ἔργον εἴη, τοὺς τῇ ὀλιγαρχίᾳ ἐναντίους κολάζειν. οἱ δὲ βουλευταὶ ἐσκόπουν τί ποιήσειαν καὶ πῶς τῷ ἀνδρὶ βοηθήσειαν. τὸν μὲν λόγον ἤκουον, τὴν δὲ τῶν ὅπλων δύναμιν ἑώρων.","gloss":[{"greek":"εὐμενῶς","english":"favorably"},{"greek":"ἔνοπλοι","english":"armed"},{"greek":"εἴη","english":"was; oblique optative"},{"greek":"βουλευταὶ","english":"councilors"},{"greek":"ποιήσειαν","english":"should do; aorist optative"},{"greek":"βοηθήσειαν","english":"might help; aorist optative"}]},{"greek":"Ὁ οὖν Κριτίας τὸ τοῦ Θηραμένους ὄνομα ἐκ τοῦ καταλόγου ἐξήλειψεν. ἔπειτα ἔλεγεν ὅτι τοῖς Τριάκοντα ἐξείη τοῦτον ἀποκτείνειν. οὕτως ὁ ἄνθρωπος, ὃς πρότερον κρίσεως ἐτύγχανεν, ἐξαίφνης ἄνευ τῆς αὐτῆς φυλακῆς ἦν. ἡ γραφὴ μετεβλήθη, ἀλλὰ τὸ πρᾶγμα οὐ διὰ τοῦτο δικαιότερον ἐγένετο. τὴν γὰρ ἀσφάλειαν ὁ κατηγορῶν αὐτὸς ἀφῄρει.","gloss":[{"greek":"ἐξήλειψεν","english":"erased"},{"greek":"ἐξείη","english":"was permitted; optative of ἔξεστι"},{"greek":"ἐτύγχανεν","english":"enjoyed, obtained; with genitive"},{"greek":"ἐξαίφνης","english":"suddenly"},{"greek":"μετεβλήθη","english":"was changed"},{"greek":"ἀφῄρει","english":"was removing"}]},{"greek":"Ὁ Θηραμένης πρὸς τὸν βωμὸν κατέφυγεν καὶ τοὺς θεοὺς καὶ τοὺς ἀνθρώπους ἐπεκαλεῖτο. ὁ δὲ Κριτίας τοῖς Ἕνδεκα παρέδωκεν αὐτόν. οἱ ὑπηρέται ἀπὸ τοῦ βωμοῦ ἀπέσπων, οἱ δὲ βουλευταὶ ἡσύχαζον φοβούμενοι. ὁ συγγραφεὺς τὴν ἀδικίαν οὐ νόμῳ γεγραμμένῳ μόνον δείκνυσιν, ἀλλὰ καὶ τοῖς σώμασι καὶ τῇ σιωπῇ τῶν παρόντων.","gloss":[{"greek":"βωμὸν","english":"altar"},{"greek":"κατέφυγεν","english":"fled for refuge"},{"greek":"ἐπεκαλεῖτο","english":"called upon"},{"greek":"Ἕνδεκα","english":"the Eleven, officials"},{"greek":"ἀπέσπων","english":"were dragging away"},{"greek":"σιωπῇ","english":"silence"}]},{"greek":"Ἐν τῇ ἡμετέρᾳ ἀσκήσει ἐρωτῶμεν τίς τὴν ψῆφον δοίη, τίς τὸν νόμον θείη, καὶ τίς τὸν φυλακῆς δεόμενον ἀφείη. ταῦτα οὐ νέαι μαρτυρίαι εἰσίν, ἀλλὰ τῆς διηγήσεως ἐξέτασις. ἡ γὰρ ὀρθὴ γραμματικὴ δεῖ καὶ τοὺς ποιοῦντας σαφεῖς ποιεῖν. μὴ τὸ «ἐκρίθη» λέγωμεν οὕτως, ὥστε κρύπτειν τίς ἔκρινεν καὶ τίς τὴν κρίσιν ἐκώλυσεν.","gloss":[{"greek":"δοίη","english":"might give; aorist optative of δίδωμι"},{"greek":"θείη","english":"might establish; of τίθημι"},{"greek":"ἀφείη","english":"might release; of ἀφίημι"},{"greek":"δεόμενον","english":"needing"},{"greek":"ἐκρίθη","english":"was judged"},{"greek":"ἐκώλυσεν","english":"prevented"}]}],"translation":"After the Athenians’ defeat the Thirty ruled the city. Critias and Theramenes were among them. They did not agree about everything: Theramenes thought the government narrower than it should be, while Critias considered him an obstacle. The rulers sought more power, and the citizens feared that each might be the next to perish.\n\nThere was a list of three thousand citizens. Those on the list had to be judged by the council before execution, while the Thirty could kill those outside it. The list was therefore not merely a record of names: it made a difference to safety. Theramenes was among those on it and claimed judgment by the council.\n\nCritias, seeing the council favorably disposed toward Theramenes, did not wish to risk the vote. Armed men were present. He said that it was the rulers’ duty to punish opponents of the oligarchy. The councilors considered what they should do and how they might help the man. They heard the argument, but saw the power of weapons.\n\nCritias therefore erased Theramenes’ name from the list. He then said that the Thirty were permitted to kill him. Thus the man who previously enjoyed a right to judgment suddenly lacked the same protection. The record was changed, but the act did not thereby become more just. For the accuser himself was removing the protection.\n\nTheramenes fled to the altar and called on gods and humans. Critias handed him over to the Eleven. The attendants dragged him from the altar, while the councilors remained quiet out of fear. The writer shows injustice not only through a written rule but also through the bodies and silence of those present.\n\nIn our exercise we ask who might give the vote, who might establish the rule, and who might release the person needing protection. These are not new testimonies but an examination of the narrative. For accurate grammar should also make the agents clear. Let us not say “he was judged” in a way that conceals who judged and who prevented judgment.\n","sourceCitation":"Xenophon, Hellenica 2.3.50–56, with context summarized from 2.3.15–20. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1174/1174-h/1174-h.htm","notesMarkdown":"Based on Hellenica 2.3.50–56, with context from 2.3.15–20. The indirect questions and reporting frames are teaching compositions. Theramenes was himself an oligarch; scrutiny of his seizure does not absolve his earlier political conduct."}$old$::jsonb;
  new_reading jsonb := $new${"title":"Ὅταν ὁ φόβος τὸν νόμον λύῃ","audioPlaceholder":"Reading audio has not yet been recorded.","introduction":["Xenophon, Hellenica 2.3.50–56, with context summarized from 2.3.15–20. 339 Greek words in 6 paragraphs.","Based on Hellenica 2.3.50–56, with context from 2.3.15–20. The indirect questions and reporting frames are teaching compositions. Theramenes was himself an oligarch; scrutiny of his seizure does not absolve his earlier political conduct.","Read once for the argument, then translate paragraph by paragraph. Try each paragraph before opening glosses; finish the final two paragraphs as connected prose. Submit your connected English translation using the reading submission box.","The vocabulary panel separates new required entries from review words. Paragraph glosses supply additional reading support; a gloss alone does not make a word or an advanced construction a production requirement."],"paragraphs":[{"greek":"Μετὰ τὴν τῶν Ἀθηναίων ἧτταν οἱ Τριάκοντα τῆς πόλεως ἦρχον. ἐν δὲ τούτοις Κριτίας καὶ Θηραμένης ἦσαν. οὐ περὶ πάντων ὡμολόγουν· ὁ Θηραμένης τὴν ἀρχὴν στενωτέραν τοῦ προσήκοντος ἐνόμιζεν, ὁ δὲ Κριτίας αὐτὸν ἐμπόδιον ἑαυτῷ ἡγεῖτο. οἱ μὲν γὰρ ἄρχοντες πλείω δύναμιν ἐζήτουν, οἱ δὲ πολῖται ἐφοβοῦντο μὴ ἕκαστος αὐτῶν ὁ ἑξῆς ἀπολοίτο.","gloss":[{"greek":"ἧτταν","english":"defeat"},{"greek":"Τριάκοντα","english":"the Thirty"},{"greek":"στενωτέραν","english":"narrower"},{"greek":"ἐμπόδιον","english":"obstacle"},{"greek":"ἑξῆς","english":"next"},{"greek":"ἀπολοίτο","english":"might perish; optative after past fear"}]},{"greek":"Κατάλογος τρισχιλίων πολιτῶν ἦν. τοὺς μὲν ἐν τῷ καταλόγῳ ὄντας τὴν βουλὴν πρὸ τοῦ θανάτου κρίνειν ἔδει, τοὺς δὲ ἔξω οἱ Τριάκοντα ἀποκτείνειν ἐδύναντο. ὁ κατάλογος οὖν οὐκ ἦν τῶν ὀνομάτων γραφὴ μόνον, ἀλλὰ πρὸς τὴν ἀσφάλειαν διαφορὰν ἐποίει. ὁ Θηραμένης τῶν ἐν τῷ καταλόγῳ ἦν καὶ τὴν κρίσιν τῆς βουλῆς ἠξίου.","gloss":[{"greek":"κατάλογος","english":"list"},{"greek":"τρισχιλίων","english":"three thousand"},{"greek":"βουλὴ","english":"council"},{"greek":"ἔξω","english":"outside"},{"greek":"ἀσφάλειαν","english":"safety"},{"greek":"ἠξίου","english":"claimed, demanded"}]},{"greek":"Ὁ Κριτίας, ὁρῶν τὴν βουλὴν εὐμενῶς πρὸς Θηραμένην ἔχουσαν, οὐκ ἐβούλετο κινδυνεύειν τὴν ψῆφον. ἔνοπλοι δὲ ἄνδρες παρῆσαν. ἔλεγεν ὅτι τοῦτο τῶν ἀρχόντων ἔργον εἴη, τοὺς τῇ ὀλιγαρχίᾳ ἐναντίους κολάζειν. οἱ δὲ βουλευταὶ ἐσκόπουν τί ποιήσειαν καὶ πῶς τῷ ἀνδρὶ βοηθήσειαν. τὸν μὲν λόγον ἤκουον, τὴν δὲ τῶν ὅπλων δύναμιν ἑώρων.","gloss":[{"greek":"εὐμενῶς","english":"favorably"},{"greek":"ἔνοπλοι","english":"armed"},{"greek":"εἴη","english":"was; oblique optative"},{"greek":"βουλευταὶ","english":"councilors"},{"greek":"ποιήσειαν","english":"should do; aorist optative"},{"greek":"βοηθήσειαν","english":"might help; aorist optative"}]},{"greek":"Ὁ οὖν Κριτίας τὸ τοῦ Θηραμένους ὄνομα ἐκ τοῦ καταλόγου ἐξήλειψεν. ἔπειτα ἔλεγεν ὅτι τοῖς Τριάκοντα ἐξείη τοῦτον ἀποκτείνειν. οὕτως ὁ ἄνθρωπος, ὃς πρότερον κρίσεως ἐτύγχανεν, ἐξαίφνης ἄνευ τῆς αὐτῆς φυλακῆς ἦν. ἡ γραφὴ μετεβλήθη, ἀλλὰ τὸ πρᾶγμα οὐ διὰ τοῦτο δικαιότερον ἐγένετο. τὴν γὰρ ἀσφάλειαν ὁ κατηγορῶν αὐτὸς ἀφῄρει.","gloss":[{"greek":"ἐξήλειψεν","english":"erased"},{"greek":"ἐξείη","english":"was permitted; optative of ἔξεστι"},{"greek":"ἐτύγχανεν","english":"enjoyed, obtained; with genitive"},{"greek":"ἐξαίφνης","english":"suddenly"},{"greek":"μετεβλήθη","english":"was changed"},{"greek":"ἀφῄρει","english":"was removing"}]},{"greek":"Ὁ Θηραμένης πρὸς τὸν βωμὸν κατέφυγεν καὶ τοὺς θεοὺς καὶ τοὺς ἀνθρώπους ἐπεκαλεῖτο. ὁ δὲ Κριτίας τοῖς Ἕνδεκα παρέδωκεν αὐτόν. οἱ ὑπηρέται ἀπὸ τοῦ βωμοῦ ἀπέσπων, οἱ δὲ βουλευταὶ ἡσύχαζον φοβούμενοι. ὁ συγγραφεὺς τὴν ἀδικίαν οὐ νόμῳ γεγραμμένῳ μόνον δείκνυσιν, ἀλλὰ καὶ τοῖς σώμασι καὶ τῇ σιωπῇ τῶν παρόντων.","gloss":[{"greek":"βωμὸν","english":"altar"},{"greek":"κατέφυγεν","english":"fled for refuge"},{"greek":"ἐπεκαλεῖτο","english":"called upon"},{"greek":"Ἕνδεκα","english":"the Eleven, officials"},{"greek":"ἀπέσπων","english":"were dragging away"},{"greek":"σιωπῇ","english":"silence"},{"greek":"γεγραμμένῳ","english":"written; perfect passive participle, dative singular; supported reading vocabulary"}]},{"greek":"Ἐν τῇ ἡμετέρᾳ ἀσκήσει ἐρωτῶμεν τίς τὴν ψῆφον δοίη, τίς τὸν νόμον θείη, καὶ τίς τὸν φυλακῆς δεόμενον ἀφείη. ταῦτα οὐ νέαι μαρτυρίαι εἰσίν, ἀλλὰ τῆς διηγήσεως ἐξέτασις. ἡ γὰρ ὀρθὴ γραμματικὴ δεῖ καὶ τοὺς ποιοῦντας σαφεῖς ποιεῖν. μὴ τὸ «ἐκρίθη» λέγωμεν οὕτως, ὥστε κρύπτειν τίς ἔκρινεν καὶ τίς τὴν κρίσιν ἐκώλυσεν. Συγκρίνομεν δὲ δύο ἐρωτήσεις· τίς ἂν τοὺς νόμους τιθείη; τίς ἂν τόνδε τὸν νόμον θείη; ἡ μὲν πρώτη περὶ τοῦ νόμους τιθέναι πολλάκις ἐρωτᾷ, ἡ δὲ δευτέρα μίαν πρᾶξιν ὡς ὅλην σκοπεῖ.","gloss":[{"greek":"δοίη","english":"might give; aorist optative of δίδωμι"},{"greek":"θείη","english":"might establish; of τίθημι"},{"greek":"ἀφείη","english":"might release; of ἀφίημι"},{"greek":"δεόμενον","english":"needing"},{"greek":"ἐκρίθη","english":"was judged"},{"greek":"ἐκώλυσεν","english":"prevented"},{"greek":"τιθείη","english":"might be setting; present active optative of τίθημι with ἄν"},{"greek":"θείη","english":"might establish; aorist active optative of τίθημι"},{"greek":"τόνδε","english":"this particular; demonstrative accusative"}]}],"translation":"After the Athenians’ defeat the Thirty ruled the city. Critias and Theramenes were among them. They did not agree about everything: Theramenes thought the government narrower than it should be, while Critias considered him an obstacle. The rulers sought more power, and the citizens feared that each might be the next to perish.\n\nThere was a list of three thousand citizens. Those on the list had to be judged by the council before execution, while the Thirty could kill those outside it. The list was therefore not merely a record of names: it made a difference to safety. Theramenes was among those on it and claimed judgment by the council.\n\nCritias, seeing the council favorably disposed toward Theramenes, did not wish to risk the vote. Armed men were present. He said that it was the rulers’ duty to punish opponents of the oligarchy. The councilors considered what they should do and how they might help the man. They heard the argument, but saw the power of weapons.\n\nCritias therefore erased Theramenes’ name from the list. He then said that the Thirty were permitted to kill him. Thus the man who previously enjoyed a right to judgment suddenly lacked the same protection. The record was changed, but the act did not thereby become more just. For the accuser himself was removing the protection.\n\nTheramenes fled to the altar and called on gods and humans. Critias handed him over to the Eleven. The attendants dragged him from the altar, while the councilors remained quiet out of fear. The writer shows injustice not only through a written rule but also through the bodies and silence of those present.\n\nIn our exercise we ask who might give the vote, who might establish the rule, and who might release the person needing protection. These are not new testimonies but an examination of the narrative. For accurate grammar should also make the agents clear. Let us not say “he was judged” in a way that conceals who judged and who prevented judgment. We compare two questions: who might regularly set the rules? Who might establish this particular rule? The first asks about repeatedly setting rules; the second views a single action as a whole.\n","sourceCitation":"Xenophon, Hellenica 2.3.50–56, with context summarized from 2.3.15–20. Independently composed course adaptation, not a verbatim quotation. https://www.gutenberg.org/files/1174/1174-h/1174-h.htm","notesMarkdown":"Based on Hellenica 2.3.50–56, with context from 2.3.15–20. The indirect questions and reporting frames are teaching compositions. Theramenes was himself an oligarch; scrutiny of his seizure does not absolve his earlier political conduct."}$new$::jsonb;
  lid uuid; rid uuid; current_reading jsonb; p jsonb; g jsonb; pi integer := 0; gi integer;
BEGIN
  SELECT id INTO STRICT lid FROM public.lessons WHERE slug='lesson-43' FOR UPDATE;
  SELECT content->'reading' INTO STRICT current_reading FROM public.lesson_content_overrides WHERE lesson_id=lid FOR UPDATE;
  IF current_reading = new_reading THEN RETURN; END IF;
  IF current_reading IS DISTINCT FROM old_reading THEN RAISE EXCEPTION 'Lesson 43 reading changed since audit baseline; refusing overwrite'; END IF;
  SELECT id INTO STRICT rid FROM public.readings WHERE lesson_id=lid ORDER BY sort_order,id LIMIT 1 FOR UPDATE;
  UPDATE public.lesson_content_overrides SET content=jsonb_set(content,'{reading}',new_reading),version=version+1,updated_at=now() WHERE lesson_id=lid;
  UPDATE public.readings SET greek_text=(SELECT string_agg(p->>'greek',E'\n\n' ORDER BY n) FROM jsonb_array_elements(new_reading->'paragraphs') WITH ORDINALITY t(p,n)),translation=new_reading->>'translation',notes_markdown=new_reading->>'notesMarkdown',source_citation=new_reading->>'sourceCitation' WHERE id=rid;
  DELETE FROM public.reading_glosses WHERE lesson_id=lid AND reading_id=rid;
  FOR p IN SELECT value FROM jsonb_array_elements(new_reading->'paragraphs') LOOP
    gi:=0;
    FOR g IN SELECT value FROM jsonb_array_elements(p->'gloss') LOOP
      INSERT INTO public.reading_glosses (lesson_id,reading_id,greek,english,lemma,display_form,part_of_speech,morphology,source,sort_order)
      VALUES (lid,rid,g->>'greek',g->>'english',g->>'greek',g->>'greek','Reading gloss','{}'::jsonb,'lesson_reading_gloss',pi*1000+gi);
      gi:=gi+1;
    END LOOP;
    pi:=pi+1;
  END LOOP;
  UPDATE public.lesson_content_blocks b SET content=jsonb_set(b.content,'{value}',new_reading),updated_at=now()
  FROM public.lesson_segments s WHERE b.segment_id=s.id AND s.lesson_id=lid AND b.content->>'source'='lesson_publish' AND b.content->>'kind'='reading';
END
